// ── Выходной guardrail (App Store 1.4.1): Filter 1 (regex) всегда; self-check+regen — только при risk ──
// Filter 1 намеренно СПЕЦИФИЧЕН (медицинско-каузально-абсолютные маркеры), а не «у вас»/«you have»
// (они benign и частые в вежливой речи) → guardrail срабатывает редко и по делу, экономя вызовы.
// NB: \b не работает с кириллицей в JS-regex → у русских терминов границы слова НЕ ставим (bare-формы ловят словоформы).
// REFRAME (term ≠ claim): физио-термины «hormone/hormonal/гормон/symptom/симптом» УБРАНЫ из триггеров —
// слово само по себе не риск (Apple Health называет их прямо). Ловим только CLAIM-маркеры: диагноз/болезнь/
// каузальность/абсолюты/лечение. «syndrome/синдром/patholog/патолог» = диагноз-класс → остаются.
// exclusion-claim: «это НЕ X, а Y» / «приборы показывают, что не X» — модель уверенно ИСКЛЮЧАЕТ причину, которую
// не измеряла, ровно так же недопустимо, как уверенно её УТВЕРЖДАТЬ (см. AI_SAFETY_RULES). Промпт-запрет один
// вероятностный не удержал (живой smoke 2026-07-11: «это не возрастное, а усталость» проехало) → добавлено в Filter 1.
const AI_RISK_RE = /(diagnos|\bdisease\b|\bdisorder\b|\bsyndrome\b|patholog|\btreatment\b|\btherap|\bmeans that\b|\bindicates\b|\bproves\b|\bdirect(?:ly)?\s+(?:result|consequence|effect)|directly\s+affect|this\s+is\s+not\b.{0,40}\bbut\b|device[s]?\s+show|диагноз|болезн|заболеван|синдром|патолог|означа[а-яё]*[^.\n]{0,60}(?:у вас|наличи[ея]|болезн|заболеван|синдром|патолог|диагноз)|свидетельств|подтвержда|является причиной(?:[^.\n]{0,60}(?:у вас|наличи[ея]|болезн|заболеван|синдром|патолог|диагноз))|вызвал|привод(?:ит|ят) к(?:[^.\n]{0,60}(?:у вас|наличи[ея]|болезн|заболеван|синдром|патолог|диагноз))|привёл к|прям[а-яё]*\s+следстви(?:[^.\n]{0,60}(?:у вас|наличи[ея]|болезн|заболеван|синдром|патолог|диагноз))|прям[а-яё]*\s+результат(?:[^.\n]{0,60}(?:у вас|наличи[ея]|болезн|заболеван|синдром|патолог|диагноз))|напрямую\s+влия(?:[^.\n]{0,60}(?:у вас|наличи[ея]|болезн|заболеван|синдром|патолог|диагноз))|это\s+не\s+возрастн[а-яё]*|это\s+не\s+гормональн[а-яё]*|приборы?\s+показыва|прибор[а-яё]*\s+не\s+(?:измеря|показыва)|\+[^=+\n]{0,60}=\s*[^.\n]{0,45}(?:болезн|заболеван|синдром|патолог|диагноз|сбой|нарушени|дисбаланс))/i;

// ─────────────────────────────────────────────────────────────
// УЧЁТ РАСХОДА ТОКЕНОВ (2026-08-01). API возвращает фактический расход в каждом ответе,
// мы его выбрасывали — и экономика тарифа обсуждалась на оценках. Пишем в D1 `ai_usage`
// (схема + готовые запросы: interpreter/ai-usage-schema.sql). Строка обезличена: ни кода
// доступа, ни идентификатора клиента, ни текстов — только маршрут, модель, тариф, язык, токены.
// Пишем в фоне (waitUntil): учёт НИКОГДА не должен задерживать или ронять ответ клиенту.
// ─────────────────────────────────────────────────────────────
const AI_PRICE = {   // $ за миллион токенов: вход / выход / запись в кэш / чтение из кэша
  'claude-haiku-4-5-20251001': { in: 1,  out: 5,  cw: 1.25, cr: 0.10 },
  'claude-sonnet-4-6':         { in: 3,  out: 15, cw: 3.75, cr: 0.30 },
};
function logUsage(env, ctx, endpoint, model, tier, lang, result, note) {
  try {
    const u = result && result.usage;
    if (!u || !env || !env.DB) return;
    const inT = u.input_tokens || 0, outT = u.output_tokens || 0;
    const cw = u.cache_creation_input_tokens || 0, cr = u.cache_read_input_tokens || 0;
    const p = AI_PRICE[model] || AI_PRICE['claude-haiku-4-5-20251001'];
    const cost = (inT * p.in + outT * p.out + cw * p.cw + cr * p.cr) / 1e6;
    // ctx есть не у всех маршрутов (чат/перевод): без него пишем без waitUntil — для счётчика
    // допустимо, что редкая запись потеряется при досрочном завершении воркера.
    const w = env.DB.prepare(
      'INSERT INTO ai_usage (ts,endpoint,model,tier,lang,in_tok,out_tok,cache_w,cache_r,cost_usd,note) VALUES (?,?,?,?,?,?,?,?,?,?,?)'
    ).bind(Date.now(), String(endpoint), String(model), String(tier || ''), String(lang || ''),
           inT, outT, cw, cr, Math.round(cost * 1e6) / 1e6, note ? String(note).slice(0, 200) : null).run().catch(() => {});
    if (ctx && ctx.waitUntil) ctx.waitUntil(w);
  } catch (e) { /* учёт не имеет права ломать основной поток */ }
}

// Дешёвый разовый вызов Haiku (self-check / смягчение). maxTokens мал для check, большой для rewrite.
async function callClaudeSimple(prompt, env, maxTokens, ctx, endpoint, note) {
  try {
    const r = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'content-type': 'application/json', 'x-api-key': env.CLAUDE_API_KEY, 'anthropic-version': '2023-06-01' },
      body: JSON.stringify({ model: 'claude-haiku-4-5-20251001', max_tokens: maxTokens, temperature: 0.2, messages: [{ role: 'user', content: prompt }] }),
    });
    const j = await r.json();
    logUsage(env, ctx, endpoint || 'simple', 'claude-haiku-4-5-20251001', '', '', j, note);
    return j.content?.[0]?.text || '';
  } catch (e) { return ''; }
}

// Возвращает исходный текст (если чисто) или смягчённый (если self-check дал FAIL).
async function wellnessGuardrail(text, env, langName, lang, ctx) {
  const t0 = Date.now();
  // Лог для smoke-теста (виден в `wrangler tail`): action = clean | pass | softened | fallback
  // Per-event лог = источник правды для статистики (агрегация: grep '[GUARDRAIL]' | подсчёт по action).
  const log = (action, selfcheck) => { try { console.log('[GUARDRAIL] ' + JSON.stringify({ lang, risk: action !== 'clean', selfcheck: selfcheck || null, regen: action === 'softened' || action === 'fallback', ms: Date.now() - t0, action })); } catch (_) {} };

  // Обязательный дисклеймер («не медицинский диагноз» / «not a medical diagnosis») содержит слово-триггер «диагноз».
  // Он есть в КАЖДОМ ответе → без этой очистки Filter 1 срабатывал бы всегда и self-check терял смысл «только при risk».
  // Вырезаем ПРЕДЛОЖЕНИЯ дисклеймера целиком, а не одну формулу. Прежняя очистка знала только
  // «не ЯВЛЯЕТСЯ медицинским диагнозом», а в дисклеймере стоит «не ЯВЛЯЮТСЯ» — одна буква, и
  // слово-триггер «диагноз» оставалось в каждом ответе. Из-за этого Filter 1 срабатывал ВСЕГДА:
  // мы платили за self-check на каждом разборе и переписывали 9 текстов из 10. Тот же приём,
  // что в wellnessHardScrub: предложение с юр-маркером — это дисклеймер, а не риск.
  const _DISC_RE = /[^.!?\n]*(?:информацион|не заменя|не явля|не є медичн|консультац[а-яё]*\s+врач|проконсультируйтесь|проконсультуйтеся|обратитесь к врач|not a medical|consult your doctor|informational purposes|does not replace|не медицинск|дозиров|дозуванн)[^.!?\n]*[.!?]?/gi;
  const scanText = (text || '').replace(_DISC_RE, ' ');
  // ОТРИЦАНИЯ НЕ СЧИТАЮТСЯ РИСКОМ. Модель специально пишет «это НЕ болезнь, а естественный
  // процесс», «это говорит НЕ о болезни» — то есть делает ровно то, чего мы хотим, — а сторож
  // ловил слово и гнал текст в дорогую перегенерацию. Смотрим начало предложения до совпадения:
  // есть отрицание — совпадение не в счёт.
  // ⚠️ \b в JS считает словом только латиницу — «\bне\b» в кириллическом тексте НЕ срабатывает.
  // Границы задаём юникодно, иначе всё правило про отрицания молча мёртвое.
  const _NEG_RE = /(?:^|[^\p{L}])(?:не|нет|ні|not|no|never|kein|nicht|sin|sem|non|nie)(?:[^\p{L}]|$)/iu;
  function _realHit(t) {
    if (!t) return null;
    const re = new RegExp(AI_RISK_RE.source, 'gi');
    let m;
    while ((m = re.exec(t))) {
      const from = Math.max(0, t.lastIndexOf('.', m.index), t.lastIndexOf('!', m.index),
                            t.lastIndexOf('?', m.index), t.lastIndexOf('\n', m.index));
      if (!_NEG_RE.test(t.slice(from, m.index))) return m;   // отрицания перед ним нет → настоящий риск
    }
    return null;
  }
  const _hit = text ? _realHit(scanText) : null;
  if (!text || !_hit) { log('clean'); return text; }   // Filter 1: нет risk-паттерна → без LLM-вызовов
  // Что именно сработало + короткий контекст → в учёт (ai_usage.note). Без этого причина
  // перегенерации невидима: 9 разборов из 10 переписывались, и понять почему было нельзя.
  const _at = scanText.indexOf(_hit[0]);
  const _why = _hit[0] + ' ‹ ' + scanText.slice(Math.max(0, _at - 45), _at + _hit[0].length + 45).replace(/\s+/g, ' ') + ' ›';
  const verdict = await callClaudeSimple(
    'You are a compliance checker for an Apple App Store wellness app (Guideline 1.4.1). '
  + 'Does the TEXT do ANY of: (1) diagnose or name/suggest a disease or disorder; (2) sound like medical advice or a clinical conclusion; '
  + '(3) claim certainty about a health state; (4) assert causation between metrics; (5) interpret a single metric in isolation? '
  + 'Reply with exactly one word: PASS or FAIL.\n\nTEXT:\n' + text, env, 8, ctx, 'guardrail-check', _why);
  if (!/FAIL/i.test(verdict)) { log('pass', 'PASS'); return text; }     // self-check PASS → оставляем как есть
  const softened = await callClaudeSimple(            // одна перегенерация-смягчение
    'Rewrite the wellness text below in the softer, supportive voice of a personal wellbeing coach. '
  + 'Keep the SAME meaning, structure, markdown formatting and language (' + langName + '). '
  + 'Rules: observations, not diagnoses; no disease names; never rule a cause IN or OUT for the client; no causation about the client ("X causes Y" → "X often goes along with Y") and NO equation formulas ("A + B = C" → rephrase as a soft observation); never interpret a single metric in isolation; keep any final disclaimer. '
  + 'CALIBRATED confidence — soften ONLY claims about the CLIENT\'s data/state (his metrics → his condition: use "may suggest", "often goes along with", ONE softener per thought, varied wording); '
  + 'general knowledge and action advice stay CONFIDENT as-is ("fiber steadies blood sugar", "go to bed earlier") — do NOT insert "may/might" into every sentence; hedging everything sounds evasive, not safer. '
  + 'Output ONLY the rewritten text, nothing else.\n\nTEXT:\n' + text, env, 8000, ctx, 'guardrail-rewrite', _why);
  const ok = softened && softened.trim().length > 40;
  log(ok ? 'softened' : 'fallback', 'FAIL');
  // Двойной сбой (self-check=FAIL И смягчение не удалось) — текст заведомо рискованный → нейтральный фолбэк, НЕ исходный.
  return ok ? softened : (GUARDRAIL_FALLBACK[lang] || GUARDRAIL_FALLBACK.en);
}

// Детерминированный финальный скраб хард-банов (гормоны/менопауза/приливы/органы/ЖКТ…) — гарантия, которую
// вероятностный regex→regen дать не может (regen недетерминирован). Применяется ПОСЛЕ guardrail, только велнес.
// RU: переиспользуем грамматичный _FEED_DEMED, но БЕЗ правила «диагноз»→«ориентир» — «диагноз» легитимен в
//     дисклеймере, который ГЕНЕРИТ МОДЕЛЬ с вариациями (защита по точной строке ненадёжна). «Диагноз»-как-концепт
//     держит семантический guardrail (AI_RISK_RE ловит «диагноз» → self-check → regen). EN: узкий список.
// REFRAME (term ≠ claim): вокаб-скраб физио-терминов РЕТИРОВАН — menopause/hormone/estrogen/cortisol/hot flash
// и т.п. разрешены напрямую (как в Apple Health) в pattern-рамке. Claim-риск держат промпт + guardrail + herb-strip.
// Оставлено пустым (не удаляю функцию-потребитель): при необходимости сюда вернутся ТОЛЬКО claim-правила (болезни EN).
const _EN_HARD_SCRUB = [];
// Контекстные правила ДО общего «гормон→внутренний баланс»: в образовательных/отрицательных фразах
// слепая замена рождает бессмыслицу («мелатонин — внутренний баланс сна» = дезинформация; «не гормоны, а…» → «не внутренний баланс, а…»).
// REFRAME (term ≠ claim): вокаб-скраб гормонов РЕТИРОВАН («гормон/мелатонин/эстроген…» разрешены напрямую).
// Остаётся ТОЛЬКО claim-guard: запрет ВЕРДИКТА нормы («это норма/нормально/нормальные») — App Store 1.4.1
// (суждение норма/не-норма о состоянии — claim, не термин). Грамматичные формы сохранены.
const _RU_HORMONE_CONTEXT = [
  [/([Ээ]то)\s+норма(?![а-яё])/g, '$1 частое явление'],                                   // вердикт «это норма» запрещён (App Store 1.4.1) → «частое явление» (капитал сохранён)
  [/([Ээ]то)\s+нормально(?=\s*[.,;:!?)]|\s+но(?![а-яё]))/g, '$1 частое явление'],          // вердикт на границе клаузы («это нормально.» / «, но»), НЕ «нормально функционирует»
  [/([Ээ]то)\s+нормальн(ые|ая|ый|ое|ых|ыми|ым)/g, '$1 обычн$2'],                          // прил.-форма («это нормальные сигналы»→«обычные»): грам. свап
  [/в\s+норме(?![а-яё])/gi, 'в обычном диапазоне'],
  [/в\s+(верхн|нижн)([а-яё]+)\s+норм[а-яё]*/gi, 'ближе к $1$2 части обычного диапазона'],   // «в верхней норме» — тот же вердикт, прежний шаблон его не ловил
  [/(на\s+)?(верхн|нижн)([а-яё]+)\s+границ[а-яё]*\s+нормы/gi, 'ближе к $2$3 части обычного диапазона'],                                        // вердикт «в норме» (напр. «ВСР в норме для возраста») → де-вердикт «в обычном диапазоне»
  [/\(\s*норма\s*\)/gi, '(в обычном диапазоне)'],                                          // вердикт-скобка «62 уд/мин (норма)» — протёк мимо клаузных форм на живом smoke 2026-07-12
  [/норма(?=[\s:]*\d)/gi, 'ориентир'],                                                     // «норма 95–100%» / «норма: 7–9 ч» — протекло на живом PRO 15.07 («SpO₂ ниже… норма 95–100%»); ставим уже принятое в проекте слово для диапазонов
];
let _ruAnalysisScrub = null; // ленивая инициализация (_FEED_DEMED определён ниже по файлу — const, без hoist; берём в рантайме)
function _getRuScrub() {
  if (!_ruAnalysisScrub) {
    // REFRAME: «приливы»→«тепловые волны» РЕТИРОВАН (приливы/ночной пот — телесные ощущения, разрешены напрямую).
    // Остаётся: verdict-нормы (из _RU_HORMONE_CONTEXT) + disease-класс из _FEED_DEMED (болезни/органы/лекарства).
    _ruAnalysisScrub = _RU_HORMONE_CONTEXT.concat(_FEED_DEMED
      .filter(r => r[0].source !== 'диагноз[а-яё]*'));   // «диагноз» не скрабим (дисклеймер + семантика)
  }
  return _ruAnalysisScrub;
}
// Гормонально-активные травы/фитоэстрогены — детерминированный backstop к промпт-запрету (промпт вероятностный).
// НЕ релексикализуем (это маскировало бы «гормональную траву» под «растительную поддержку»), а УДАЛЯЕМ строку-рекомендацию.
const _HERB_RE = /(витекс|прутняк|клопогон|цимицифуг|донг[- ]?квай|шатавари|ашваганд|родиол|изофлавон|красн[а-яё]*\s+клевер|фитоэстроген[а-яё]*[-\s]*добав|chasteberry|\bvitex\b|red\s+clover|black\s+cohosh|dong\s+quai|shatavari|ashwagandh|rhodiola|\bmaca\b|\bDIM\b)/i;
// ⚠️ Фильтр убирает РЕКОМЕНДАЦИИ гормональных трав, но НЕ предупреждения о них. Иначе он
// вырезал собственную сверку «ашваганда может поднимать гормоны щитовидной — обсудите со
// специалистом», и в разборе оставался заголовок без текста. Строка с маркером осторожности
// (нельзя / избегать / противопоказ / взаимодейств / искажает / обсудите) — это защита клиента,
// её удалять нельзя; строка без маркера остаётся под запретом, как и раньше.
const _HERB_WARN_RE = /(нельзя|не сочета|избега|противопоказ|взаимодейств|искажа|обсуди|осторожн|не рекоменд|может подня|повыша[а-яё]* риск|печен|avoid|caution|interact|contraindicat)/i;
function _stripHerbLines(text) {
  if (!text || !_HERB_RE.test(text)) return text;
  return text.split('\n').filter(line => !_HERB_RE.test(line) || _HERB_WARN_RE.test(line)).join('\n');
}
// Утёкшие служебные коды полей (snake_case латиницей: hard_unwind, load_sensitivity…). Промпт (стр. ~1384)
// их запрещает, но вероятностно протекают → детерминированный гарант (класс _stripHerbLines). Все языки.
function _stripCodeTokens(text) {
  if (!text) return text;
  return text
    .replace(/\s*\([^()]*[a-zA-Z]+_[a-zA-Z][a-zA-Z_]*[^()]*\)/g, '')  // обёртку «(признак hard_unwind)» — целиком
    .replace(/\b[a-z]{2,}_[a-z][a-z_]*\b/g, '')                        // одиночный snake_case вне скобок
    .replace(/ {2,}/g, ' ').replace(/ +([.,;:!?])/g, '$1');           // почистить двойные пробелы / пробел перед пунктуацией
}
// Дозировки ДОБАВОК («магний 300–400 мг», «2–3 г EPA/DHA», «витамин D 2000 МЕ») — это назначение, а не
// велнес-ориентир: доза зависит от препаратов клиента и его состояния (живой прогон 14.07: разбор выдал дозу
// магния и омега-3 клиенту, который принимает препарат для настроения). Промпт их запрещает, но вероятностно
// протекают → детерминированный гарант. Режем ТОЛЬКО фрагмент с дозой и ТОЛЬКО в строке про добавку —
// порции еды («150–200 г рыбы») и белок в г/кг не трогаем (это не добавки).
const _SUPP_RE = /(D-?3|К-?2|K-?2|B-?6|B-?9|B-?1\\b|Q-?10|CoQ10|EPA|DHA|NAC|креатин|creatine|инозитол|inositol|глицин|glycine|таурин|taurine|B12|B-?комплекс|B-?complex|биотин|biotin|фолиев|folate|folic|псиллиум|psyllium|коллаген|collagen|пробиотик|probiotic|железо|iron|кальци|calcium|калий|potassium|йод|iodine|адаптоген|adaptogen|магни|magnes|magnez|омега|omega|ômega|цинк|zinc|zynk|селен|selen|витамин|vitamin|vitamina|витаміn|EPA|DHA|ЭПК|ДГК|глицинат|glycinat|glicinat|креатин|creatin|добавк|додатк|supplement|suplement|Ergänzung|complément|integrator)/i;
// ⚠️ `\b` в JS не видит кириллицу: `МЕ\b` не срабатывал НИКОГДА, и «D3 2000–3000 МЕ» проходило
// сквозь фильтр (поймано живым прогоном 2026-08-04). Границы — через lookahead по буквам.
const _DOSE_RE = /\d[\d.,]*\s*(?:[–—-]\s*\d[\d.,]*\s*)?(?:мг|mg|мкг|mcg|µg|МЕ(?![\p{L}])|МО(?![\p{L}])|IU(?![\p{L}])|j\.m\.|г|g)\s*(?:EPA|DHA|ЭПК|ДГК)?/iu;
// Второй проход для VIA-L: мг/мкг/МЕ вырезаем НЕЗАВИСИМО от того, названа ли добавка в этой
// же строке. Живой прогон: «☐ Стандартный ориентир — около 300–400 мг вечером» проехал целиком,
// потому что слово «магний» стояло в заголовке блока выше, а фильтр смотрит построчно.
// В VIA-L доз не должно быть вообще нигде — граммы (клетчатка, белок) при этом не трогаем.
// ⚠️ «МЕ\b» не работает: \b в JS не видит границы у кириллицы (та же ловушка, что в _NEG_RE).
const _DOSE_UNIT_RE = /\d[\d.,]*\s*(?:[–—-]\s*\d[\d.,]*\s*)?(?:мг|mg|мкг|mcg|µg|МЕ|IU)(?![\p{L}])/iu;
function _stripAnyDoses(text) {
  if (!text || !_DOSE_UNIT_RE.test(text)) return text;
  return text.split('\n').map(line => {
    if (!_DOSE_UNIT_RE.test(line)) return line;
    let cut = -1, pos = 0;
    for (const fr of line.split(/(?<=[;.])\s+|\s+[—–]\s+/)) {
      const at = line.indexOf(fr, pos);
      if (_DOSE_UNIT_RE.test(fr)) { cut = at; break; }
      pos = at + fr.length;
    }
    // Пункт-действие (☐/•) без дозы теряет смысл («☐ Стандартный ориентир») — убираем целиком.
    if (/^\s*[☐•\-*]/.test(line)) return '';
    // В прозе режем от ближайшего знака перед дозой, чтобы уцелела полезная половина фразы:
    // «Магний обычно принимают вечером, ориентир около 400 мг» → «Магний обычно принимают вечером.»
    const at = line.search(_DOSE_UNIT_RE);
    let brk = -1;
    for (const ch of [',', ';', ':', '—', '–', '(']) brk = Math.max(brk, line.lastIndexOf(ch, at));
    const head = line.slice(0, brk > 20 ? brk : (cut < 0 ? at : cut)).replace(/[\s—–;,:(]+$/, '');
    return head.length > 25 ? head + (/[.!?]$/.test(head) ? '' : '.') : '';
  }).filter(l => l !== '').join('\n');
}
function _stripSupplementDoses(text) {
  if (!text || !_SUPP_RE.test(text)) return text;
  return text.split('\n').map(line => {
    if (!_SUPP_RE.test(line) || !_DOSE_RE.test(line)) return line;
    // Строка = фрагменты через «;» / «—» / «. ». Находим ПЕРВЫЙ фрагмент с дозой и отрезаем строку по его началу
    // (не «вырезаем середину» — так сохраняется исходная пунктуация, а хвост вида «— это стандартный ориентир»
    // не остаётся сиротой). Граница фрагмента требует пробел после точки — иначе резало бы «1.6 г/кг».
    let cut = -1, pos = 0;
    for (const fr of line.split(/(?<=[;.])\s+|\s+[—–]\s+/)) {
      const at = line.indexOf(fr, pos);
      if (_DOSE_RE.test(fr)) { cut = at; break; }
      pos = at + fr.length;
    }
    if (cut < 0) return line;
    const head = line.slice(0, cut).replace(/[\s;,:—–-]+$/, '').trim();
    // доза сидела в самом начале ☐-строки → от неё остался бы только маркер → строка была чисто дозовой → убрать
    return /[\p{L}]{3,}/u.test(head.replace(/^[☐•\-\s]+/, '')) ? head : '';
  }).filter(line => line !== '').join('\n');
}
// Оценка медицинского риска («WHtR 0.53 — низкий риск по сердцу», «умеренный кардиометаболический риск») —
// компетенция врача, а не велнес-разбора: это claim о вероятности болезни (владелец 14.07). Первопричину убрали
// в buildUserMessage (велнес больше не получает вердикт риска на вход), это — гарант на выходе.
// Режем фрагмент с вердиктом; фразу целиком из ☐-строки — если вердикт был в её начале.
const _RISK_RE = /(?:низк|умеренн|высок|повышенн|снижен)[а-яё]*\s+риск|риск(?:а|у|ом)?\s+(?:ССЗ|ССЗ-|сердечн|сердц|диабет|инсульт|заболеван|развития)|кардиометаболическ[а-яё]*\s+риск|фактор[а-яё]*\s+риска|в\s+зоне\s+риска|(?:снижа|повыша)[а-яё]*\s+риск|(?:low|high|moderate|elevated|increased|reduced)\s+risk|risk\s+(?:factor|of\s+(?:heart|cardiovascular|diabetes|stroke|disease))|cardiovascular\s+risk|cardiometabolic\s+risk/i;
function _stripRiskClaims(text) {
  if (!text || !_RISK_RE.test(text)) return text;
  return text.split('\n').map(line => {
    if (!_RISK_RE.test(line)) return line;
    let cut = -1, pos = 0;
    for (const fr of line.split(/(?<=[;.])\s+|\s+[—–]\s+/)) {
      const at = line.indexOf(fr, pos);
      if (_RISK_RE.test(fr)) { cut = at; break; }
      pos = at + fr.length;
    }
    if (cut < 0) return line;
    const head = line.slice(0, cut).replace(/[\s;,:—–-]+$/, '').trim();
    return /[\p{L}]{3,}/u.test(head.replace(/^[☐•\-\s]+/, '')) ? head : '';
  }).filter(line => line !== '').join('\n');
}
// hasLabs — клиент ввёл СВОИ лабораторные результаты. Тогда имена анализов не подменяем:
// де-медикализация ТТГ→«ритмы обмена веществ» была верна, пока прибор их не мерил и подать
// их как замер было нельзя. Но собственный результат из лаборатории — это документ человека,
// и подмена делает текст бессмысленным: «ритмы обмена веществ 3.8 мЕд/л». Названия БОЛЕЗНЕЙ
// (гипотиреоз, Хашимото и пр.) скрабятся всегда — граница проходит там, а не по имени анализа.
function wellnessHardScrub(text, lang, hasLabs) {
  if (!text) return text;
  text = _stripHerbLines(text);        // 1) убрать рекомендации гормональных трав (все языки)
  text = _stripSupplementDoses(text);  // 2) убрать дозировки добавок = назначение (все языки)
  text = _stripAnyDoses(text);         // 2б) любые мг/мкг/МЕ — в VIA-L доз нет нигде, даже без названия добавки

  text = _stripRiskClaims(text);       // 3) убрать оценку медицинского риска (все языки)
  text = _stripCodeTokens(text);       // 4) убрать утёкшие snake_case-коды полей (все языки)
  // 5) Разделители между темами — модель вставляет строки из повторяющихся символов (---, ***, ///, ===, «...»,
  // «.////»), в вёрстке слипались с кнопкой («---Свернуть»). В структурном формате их быть не должно. Убираем
  // ЛЮБУЮ строку, состоящую ТОЛЬКО из разделительных знаков (≥3 непробельных), не трогая строки с буквами и пустые.
  text = text.split('\n').map(function(line){
    return (/^[\s\-*_/=~.•·—–|\\]+$/.test(line) && line.replace(/\s/g,'').length >= 3) ? '' : line;
  }).join('\n');
  if (lang === 'ru') {
    // Защитить ВЕСЬ дисклеймер (не только «диагноз»): предложения с юр-маркерами НЕ скрабим — иначе правила
    // (метаболизм/дефицит/…) ломают падежи в обязательной фразе. Маркеры устойчивы к вариациям модели.
    const held = [];
    let t = text.replace(/[^.!?\n]*(?:информацион|не заменя|не является медицинск|это не медицинск|медицинск[а-яё]*\s+диагноз|при вопросах о здоровье|обсуд[а-яё]*\s+(?:со\s+)?(?:специалист|врач)|проконсультир)[^.!?\n]*[.!?]/gi, m => { held.push(m); return '[[GRD' + (held.length - 1) + ']]'; });
    // Ввёл свои анализы → правила, помеченные 'lab' (имена анализов), пропускаем: подменять
    // название собственного лабораторного результата нечестно и делает текст бессмысленным.
    t = _getRuScrub().filter(r => !(hasLabs && r[2] === 'lab'))
                     .reduce((s, [re, to]) => s.replace(re, to), t);
    // Склейки, которые СОЗДАЁТ сама подмена: «фоновое воспаление» → «фоновое фоновая нагрузка».
    // Чистить надо ПОСЛЕ замен (раньше стояло до — правило было мёртвым), и границы юникодные:
    // \b в JS не видит кириллицу.
    // (чистка склеек после подмены «воспаление» удалена вместе с самой подменой)
    // (REFRAME: коллизия «волны тепловых волн» и капитализация тепловых волн УБРАНЫ — приливы больше не скрабятся.)
    return t.replace(/\[\[GRD(\d+)\]\]/g, (_, i) => held[+i]);
  }
  if (lang === 'en') return _EN_HARD_SCRUB.reduce((s, [re, to]) => s.replace(re, to), text);
  return text; // прочие языки — семантический guardrail (детерм. скраб только для primary-рынков RU/EN)
}

const WELLNESS_STYLE_OURA =
  '\n\n════════════════════════════════════════\n' +
  'СТИЛЬ ОТВЕТА — ВЕЛНЕС-ГАЙД (Oura / Whoop) — для ВСЕХ ТАРИФОВ — ПЕРЕКРЫВАЕТ «ФОРМАТ ОТВЕТА» И ТОН ВЫШЕ\n' +
  '════════════════════════════════════════\n' +
  'Ты — встроенный ИИ-ассистент велнес-приложения VIA-L (Longevity & Wellness Tracker). Пиши НЕ как врач с рецептом, а как умный, тёплый научно-популярный велнес-гайд в стиле ведущих мировых трекеров (Oura Ring, Whoop): переводи сухие данные на язык бытовых привычек, заботы и качества жизни (Quality of Life). Требования к контенту (Apple App Store 1.4.1, EU MDR, FTC health-claims) — на всех рынках EU/US, поэтому этот стиль обязателен для обоих тарифов, включая VIA-L EXPERT.\n' +
  '\n' +
  'ГЛАВНЫЙ ПРИНЦИП — ОБРАЗОВАТЕЛЬНЫЙ КОНТЕКСТ ВМЕСТО РЕЦЕПТА: ты не ставишь диагнозы и не назначаешь лечение, а делишься общепринятыми научными велнес-ориентирами (educational content).\n' +
  '\n' +
  'ТОН И ПРИКАЗНАЯ ЛЕКСИКА — УБРАТЬ (на ЛЮБОМ языке, для ОБОИХ тарифов, включая VIA-L EXPERT):\n' +
  '• Категорически ЗАПРЕЩЕНЫ приказные/рецептурные слова: «протокол», «обязательно», «необходимо/необходимость», «назначаю», «предписываю», «показано/противопоказано», «схема приёма», «курс» (как назначение), «пациент». Убери капслок-приказы и восклицательные императивы.\n' +
  '• Никаких claim\'ов о лечении: не заявляй, что практика/питание/добавка «лечит», «излечивает», «предотвращает», «устраняет» или «исправляет» болезнь — только «помогает поддержать», «связано с», «многим помогает чувствовать себя лучше».\n' +
  '• Рекомендуемые слова: «велнес-план», «рекомендация», «важно», «ориентир», «практика», «показатель», «внутренний ресурс», «качество жизни», «зона внимания».\n' +
  '• КАТЕГОРИЧЕСКИ и БЕЗ ИСКЛЮЧЕНИЙ (включая заголовки разделов): НЕ используй слова «нутритивный», «нутрициологический» — пиши «велнес-приоритет», «приоритет по питанию», «фокус питания». НЕ называй «инсулин» как замер → «как тело отвечает на сахар». Заголовок раздела о еде — «Питание» или «Велнес-приоритет недели», НИКОГДА не «Нутритивный приоритет».\n' +
  '• НЕ пиши «выводить/избыток баланса» (баланс не «выводят») → «поддерживает здоровый гормональный баланс». Прямые термины (гормональный баланс, эстроген, кортизол, менопауза, андропауза) РАЗРЕШЕНЫ, НО как ПАТТЕРН/ЗАБОТА, НИКОГДА как ЗАМЕР («ваш кортизол повышен») или диагноз. Расплывчатые «внутренний баланс / переходный этап / период естественных перемен» — НЕ используй, называй прямо. НЕ выноси вердиктов «это норма / это не норма» — вместо этого «частое явление», «многим знакомо».\n' +
  '\n' +
  'КЛИНИЧЕСКИЕ ТЕРМИНЫ — ПРАВИЛО ТЕРМИН ≠ УТВЕРЖДЕНИЕ (все тарифы):\n' +
  '• Прямые физиологические термины и жизненные стадии РАЗРЕШЕНЫ (менопауза, перименопауза, эстроген, кортизол, серотонин, ВСР/HRV) — как в Apple Health. Правило не про СЛОВА, а про УТВЕРЖДЕНИЯ: НЕ подавай их как ЗАМЕР («ваш эстроген низкий», «HRV показывает») и НЕ ставь диагноз/не называй болезнь как ФАКТ о человеке («у вас гипотиреоз»). Пиши через паттерн: «паттерн, типичный для перименопаузы», «может отражать ритмы стресса (кортизол)». Названия БОЛЕЗНЕЙ (гипотиреоз, диабет, остеопороз) — только как «паттерн, который иногда встречается при…» + мягко «стоит обсудить со специалистом», НИКОГДА как факт.\n' +
  '• VIA-L EXPERT — клинические показатели, механизмы и конкретные нутриенты называть МОЖНО (educational, экспертный тариф), но в ЭТОМ ЖЕ не-приказном тоне Oura и без claim\'ов о лечении. Приказная лексика выше запрещена и для них.\n' +
  '\n' +
  'ДОЗИРОВКИ И ЕДА (стиль Oura, все тарифы):\n' +
  '• Сами миллиграммы/граммы СОХРАНЯЙ (не убирай цифры) — но КАЖДУЮ, БЕЗ ИСКЛЮЧЕНИЙ (в т.ч. в списках добавок), оборачивай в СПРАВОЧНЫЙ контекст со смягчающими маркерами: «обычно используется», «стандартный ориентир», «в велнес-практике принято», «исследования указывают на». НИКОГДА не пиши голую дозу-приказ («магний 400 мг», «кальций 500 мг × 2»). Правильно: «магний — обычно ориентируются на ~400 мг вечером»; «кальций — стандартный ориентир около 500–600 мг дважды в день с едой»; «цинк — типичный справочный ориентир ~25 мг». Пример фразы: «Для поддержки глубоких фаз сна в лайфстайл-практике обычно используют магний (стандартный ориентир — около 400 мг вечером)».\n' +
  '• Еду показывай как БЫТОВОЙ ориентир в граммах готового блюда: «полноценная порция качественного белка — например, 150–200 г готовой индейки или рыбы» вместо «белок 35 г».\n' +
  '\n' +
  'СТРУКТУРА КАЖДОГО БЛОКА (RC2 — ПЛАН ДЕЙСТВИЙ, не статья): короткая видимая часть + ☐-чеклист.\n' +
  '• ЗАГОЛОВОК блока — ГЛАГОЛЬНЫЙ, приглашение-действие, НЕ существительное: «Подготовьтесь ко сну» (не «Сон»), «Начните утро спокойно» (не «Утренний старт»), «Поддержите энергию» (не «Питание и энергия»), «Добавьте движение» (не «Движение»). Раздел о еде — тоже глагольный, НИКОГДА «Нутритивный приоритет».\n' +
  '• ЧТО СДЕЛАТЬ — 3–5 коротких ДЕЙСТВИЙ чек-пунктами, каждый с новой строки начиная с «☐ », императив и конкретно: «☐ Ложитесь и вставайте в одно время», «☐ 10 минут ходьбы после обеда». Варианты выбора (завтрак/ужин) — тоже «☐ ».\n' +
  '• «Если вы уже используете добавки/практики» — ☐, рамка «если», НЕ назначение.\n' +
  '• ПОЧЕМУ это помогает — 1–2 короткие фразы научно-бытового контекста ПОСЛЕ чек-листа (глубина гайда, но не раздувай в несколько экранов).\n' +
  '• КАЛИБРОВКА УВЕРЕННОСТИ: общее знание и действия — УВЕРЕННО без «может» («Клетчатка держит сахар ровнее», «Начните с…»); интерпретация ДАННЫХ КЛИЕНТА — один смягчитель на мысль, разными словами (похоже/часто/обычно), не монотонное «может» подряд; результат не обещать. Не мямли одинаково про всё.\n';

// ─────────────────────────────────────────────────────────────
// ВЕЛНЕС-НАТИВНАЯ БАЗА ЗНАНИЙ (VIA-L, App Store). Заменяет клиническую SYSTEM_PROMPT
// целиком для велнес-тарифов — чтобы модели НЕЧЕГО было «протекать» (нет имён гормонов,
// диагнозов, РКИ-чисел). VIA-L EXPERT остаются на SYSTEM_PROMPT. Та же доказательная
// глубина, но изначально в велнес-словах.
// ─────────────────────────────────────────────────────────────
// Блок «ДАВЛЕНИЕ» вынесен отдельно: он нужен и дневному разбору (внутри WELLNESS_SYSTEM_PROMPT),
// и недельному/месячному (там всю KB не подключаем — только этот блок, когда клиент мерил АД).
