export default {
  async fetch(request, env, ctx) {
    const corsHeaders = {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type, Authorization',
    };

    if (request.method === 'OPTIONS') {
      return new Response(null, { headers: corsHeaders });
    }

    const url  = new URL(request.url);
    const path = url.pathname;

    // GET routes
    if (request.method === 'GET') {
      if (path === '/intake-validate') return handleIntakeValidate(request, env, corsHeaders);
      // Имя/профиль специалиста по реф-коду — анкета `book/anketa?ref=` де-брендит шапку (§10).
      if (path === '/specialist-by-ref') return handleSpecialistByRef(request, env, corsHeaders);
      // Витрина «Мой наставник»: публичный список наставников (public=1) для выбора + записи на зум.
      if (path === '/specialists/public') return handleSpecialistsPublic(request, env, corsHeaders);
      // Fitbit OAuth2 (self-serve) — connect ring/device, pull 7-day metrics
      if (path === '/fitbit/start')    return handleFitbitStart(request, env, corsHeaders);
      if (path === '/fitbit/callback') return handleFitbitCallback(request, env, corsHeaders);
      if (path === '/fitbit/metrics')  return handleFitbitMetrics(request, env, corsHeaders);
      // WHOOP OAuth2 (self-serve)
      if (path === '/whoop/start')     return handleWhoopStart(request, env, corsHeaders);
      if (path === '/whoop/callback')  return handleWhoopCallback(request, env, corsHeaders);
      if (path === '/whoop/metrics')   return handleWhoopMetrics(request, env, corsHeaders);
      // Polar AccessLink
      if (path === '/polar/start')       return handlePolarStart(request, env, corsHeaders);
      if (path === '/polar/callback')    return handlePolarCallback(request, env, corsHeaders);
      if (path === '/polar/metrics')     return handlePolarMetrics(request, env, corsHeaders);
      // Withings Health API
      if (path === '/withings/start')    return handleWithingsStart(request, env, corsHeaders);
      if (path === '/withings/callback') return handleWithingsCallback(request, env, corsHeaders);
      if (path === '/withings/metrics')  return handleWithingsMetrics(request, env, corsHeaders);

      if (path === '/oura/start')        return handleOuraStart(request, env, corsHeaders);
      if (path === '/oura/callback')     return handleOuraCallback(request, env, corsHeaders);
      if (path === '/oura/metrics')      return handleOuraMetrics(request, env, corsHeaders);
      // Гейт EXPERT (витрина): проверка срочного кода доступа — GET, публично. См. §894.
      if (path === '/expert/verify')     return handleExpertVerify(request, env, corsHeaders);
      // Аккаунт клиента по коду: снимок состояния ИП (дневник/профиль/разборы) для любого устройства.
      if (path === '/expert/state')      return handleExpertStateGet(request, env, corsHeaders);
      // Чат клиент↔нутрициолог: чтение треда — GET (?code=). Ответ спеца переводится на язык клиента.
      if (path === '/expert/thread')     return handleExpertThread(request, env, corsHeaders, ctx);
      return new Response('Not found', { status: 404 });
    }

    if (request.method !== 'POST') {
      return new Response('Method not allowed', { status: 405 });
    }

    try {
      // Backstage Telegram bot
      if (path === '/tg-test')          return handleTgTest(request, env, corsHeaders);
      if (path === '/draft')            return handleDraft(request, env, corsHeaders);
      if (path === '/tg-webhook')       return handleTgWebhook(request, env, corsHeaders);

      // Program intake flow
      if (path === '/hotmart-webhook')  return handleHotmartWebhook(request, env, corsHeaders);
      if (path === '/intake-submit')    return handleIntakeSubmit(request, env, corsHeaders);

      // Cal.com webhook → TG-карточка нутрициологу (единый механизм записи)
      if (path === '/cal-webhook')      return handleCalWebhook(request, env, corsHeaders);

      // Клиентский бот заботы (@viael_care_bot) → переписка клиент↔нутрициолог через Topics
      if (path === '/care-webhook')     return handleCareWebhook(request, env, corsHeaders);

      // Цифровая анкета здоровья (book/anketa) → структурированная карточка в топик клиента
      if (path === '/anketa-submit')    return handleAnketaSubmit(request, env, corsHeaders, ctx);
      if (path === '/advisor-chat')     return handleAdvisorChat(request, env, corsHeaders);
      if (path === '/weekly-report')    return handleWeeklyReport(request, env, corsHeaders, ctx);

      // VIA-L EXPERT — внутренний канал связи клиент↔нутрициолог (НЕ Telegram для клиента).
      // Авторизация = код доступа (как /weekly-report). Сторона нутрициолога — в кабинете (вкладка «Переписка»).
      // (/expert/thread — GET, зарегистрирован в GET-блоке выше)
      if (path === '/expert/message')   return handleExpertMessage(request, env, corsHeaders, ctx);
      // (/expert/state — GET читает снимок, POST пишет с CAS по rev)
      if (path === '/expert/state')     return handleExpertStatePut(request, env, corsHeaders);
      if (path === '/chat/upload')      return handleChatUpload(request, env, corsHeaders);   // фото/голос в чат → R2

      // Кабинет нутрициолога (CRM на D1) — см. docs/CABINET-MODEL.md
      if (path === '/cabinet-auth')        return handleCabinetAuth(request, env, corsHeaders);
      if (path === '/cabinet/clients')     return handleCabinetClients(request, env, corsHeaders);
      if (path === '/cabinet/client')      return handleCabinetClient(request, env, corsHeaders);
      if (path === '/cabinet/save')        return handleCabinetSave(request, env, corsHeaders);
      if (path === '/cabinet/delete')      return handleCabinetDelete(request, env, corsHeaders);
      if (path === '/cabinet/ai-draft')    return handleCabinetAiDraft(request, env, corsHeaders);
      if (path === '/cabinet/tg-send')     return handleCabinetTgSend(request, env, corsHeaders);
      if (path === '/cabinet/chat-send')   return handleCabinetChatSend(request, env, corsHeaders, ctx);   // ответ спеца в чат клиента (app)
      if (path === '/cabinet/translate')   return handleCabinetTranslate(request, env, corsHeaders);
      if (path === '/cabinet/leads')       return handleCabinetLeads(request, env, corsHeaders);
      if (path === '/cabinet/showcase-save') return handleCabinetShowcaseSave(request, env, corsHeaders);   // профиль витрины специалиста

      // Платформа, Шаг 2: пациент подключается к специалисту по его коду + согласие.
      // См. docs/PLATFORM-MODEL.md §3 (публичные ручки, без cabinet-auth).
      if (path === '/specialist/connect')  return handleSpecialistConnect(request, env, corsHeaders);
      if (path === '/specialist/unlink')   return handleSpecialistUnlink(request, env, corsHeaders);

      // Воронка витрина → EXPERT PWA: специалист выдаёт клиенту СРОЧНЫЙ код доступа к
      // VIA-L EXPERT (отдельный от ref_code/кода карточки), сам управляет сроком/отзывом.
      // Гейт EXPERT проверяет код здесь ПЕРВЫМ, потом фолбэк на Apps Script (ветка Hotmart).
      // См. tasks/TODO.md §«Воронка VIA-L → витрина → EXPERT PWA».
      // (/expert/verify — GET, зарегистрирован в GET-блоке выше)
      if (path === '/cabinet/expert-grant') return handleCabinetExpertGrant(request, env, corsHeaders);   // авторизован (специалист)
      if (path === '/cabinet/expert-revoke')return handleCabinetExpertRevoke(request, env, corsHeaders);  // авторизован (специалист)
      if (path === '/cabinet/expert-extend')return handleCabinetExpertExtend(request, env, corsHeaders);  // авторизован (специалист)

      // Платформа, Шаг 6: панель владельца — управление специалистами (только role=owner).
      if (path === '/cabinet/specialists')       return handleCabinetSpecialists(request, env, corsHeaders);
      if (path === '/cabinet/billing')          return handleCabinetBilling(request, env, corsHeaders);            // владелец: сводка по деньгам
      if (path === '/complaint')               return handleComplaint(request, env, corsHeaders);                  // жалоба клиента (A5)
      if (path === '/cabinet/complaints')      return handleCabinetComplaints(request, env, corsHeaders);          // владелец: разбор жалоб
      if (path === '/offer/accept')            return handleOfferAccept(request, env, corsHeaders);               // акцепт оферты до оплаты (A2)
      if (path === '/expert/confirm-email') return handleExpertConfirmEmail(request, env, corsHeaders);   // подтверждение почты при первом входе (POST)
      if (path === '/cabinet/my-password')     return handleCabinetMyPassword(request, env, corsHeaders);           // специалист меняет свой пароль (D2)
      if (path === '/client/erase')            return handleClientErase(request, env, corsHeaders);                 // удаление данных о здоровье
      if (path === '/service-act')             return handleServiceAct(request, env, corsHeaders);                 // акт по клиенту (D3)
      if (path === '/cabinet/reassign')        return handleCabinetReassign(request, env, corsHeaders);             // передать клиента другому специалисту (B3)
      if (path === '/cabinet/expert-users')    return handleCabinetExpertUsers(request, env, corsHeaders);        // счётчик и сверка пользователей EXPERT
      if (path === '/cabinet/billing/me')       return handleCabinetBillingMe(request, env, corsHeaders);          // специалист: та же сводка про себя
      if (path === '/cabinet/billing/payment')  return handleCabinetBillingPayment(request, env, corsHeaders);     // владелец: отметить/удалить оплату
      if (path === '/cabinet/billing/detail')   return handleCabinetBillingDetail(request, env, corsHeaders);      // владелец: расшифровка по специалисту
      if (path === '/cabinet/specialist-save')   return handleCabinetSpecialistSave(request, env, corsHeaders);
      if (path === '/cabinet/specialist-delete') return handleCabinetSpecialistDelete(request, env, corsHeaders);

      // Платформа, Шаг 4: абонплата специалиста (Hotmart-подписка на доступ к платформе).
      if (path === '/specialist-access-webhook') return handleSpecialistAccessWebhook(request, env, corsHeaders);

      // Default: AI-анализ для интерпретатора
      if (path === '/day-plan') return handleDayPlan(request, env, corsHeaders, ctx);
      if (path === '/ai-memory') return handleAiMemory(request, env, corsHeaders, ctx);
      return handleAnalyze(request, env, corsHeaders, ctx);

    } catch (e) {
      return new Response(JSON.stringify({ error: e.message, stack: e.stack }), {
        status: 500,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      });
    }
  },

  // Cron Trigger (см. wrangler.jsonc "triggers.crons") — ежедневные напоминания клиентам.
  async scheduled(event, env, ctx) {
    ctx.waitUntil(runDailyReminders(env));
    ctx.waitUntil(expireSpecialistAccess(env));   // Шаг 4: закрыть доступ при истёкшей абонплате
    ctx.waitUntil(eraseExpiredHealthData(env));    // E3 §5: данные о здоровье — 90 дней после ведения
  },
};

