// PROGRAM INTAKE — Hotmart webhook
// Secrets needed: HOTMART_TOKEN, TELEGRAM_BOT_TOKEN, NUTRITIONIST_CHAT_ID
// KV binding needed: PROGRAM_INTAKES
// ─────────────────────────────────────────────────────────────
// Определяет язык клиента по данным из Hotmart payload.
// Проверяет locale, страну из нескольких возможных полей, домен email.
function detectLangFromHotmart(data) {
  const buyer    = data.buyer    || {};
  const purchase = data.purchase || {};

  // locale: "uk_UA", "ru_RU", "es_ES", "en_US"
  const locale = buyer.locale || buyer.address?.locale || '';
  if (locale) {
    const code = locale.split(/[_-]/)[0].toLowerCase();
    const SUPPORTED = ['uk','ru','es','en','de','pt','fr','pl','it','he','ja','ko'];
    if (SUPPORTED.includes(code)) return code;
  }

  // Country ISO from various possible fields
  const country = (
    buyer.checkout_country?.iso ||
    buyer.address?.country ||
    purchase.checkout_country?.iso ||
    purchase.address?.country || ''
  ).toUpperCase();

  const countryLang = {
    UA: 'uk',
    RU: 'ru', BY: 'ru', KZ: 'ru', MD: 'ru', AM: 'ru', GE: 'ru', AZ: 'ru',
    IL: 'ru',
    ES: 'es', MX: 'es', CO: 'es', AR: 'es', VE: 'es', CL: 'es', PE: 'es',
    UY: 'es', EC: 'es', BO: 'es', PY: 'es', CR: 'es', PA: 'es', GT: 'es',
    DE: 'de', AT: 'de', CH: 'de',
    PT: 'pt', BR: 'pt',
    FR: 'fr', BE: 'fr', LU: 'fr',
    PL: 'pl',
    IT: 'it',
    JP: 'ja',
    KR: 'ko',
  };
  if (country && countryLang[country]) return countryLang[country];

  // Email domain heuristic
  const emailDomain = (buyer.email || '').split('@').pop()?.split('.').pop()?.toLowerCase();
  if (emailDomain === 'ua')                   return 'uk';
  if (['ru','by','kz'].includes(emailDomain)) return 'ru';

  return 'en'; // default
}

async function handleHotmartWebhook(request, env, corsHeaders) {
  const hottok = request.headers.get('x-hotmart-hottok');
  if (env.HOTMART_TOKEN && hottok !== env.HOTMART_TOKEN) {
    return jsonResponse({ ok: false, error: 'invalid_token' }, corsHeaders, 401);
  }

  let body = {};
  try { body = await request.json(); }
  catch (e) { return jsonResponse({ ok: false, error: 'invalid_json' }, corsHeaders, 400); }

  const event = body.event;
  if (event !== 'PURCHASE_APPROVED') {
    return jsonResponse({ ok: true, skipped: event }, corsHeaders);
  }

  const data       = body.data || {};
  const productId  = data.product?.id;
  const buyerName  = data.buyer?.name  || '—';
  const buyerEmail = data.buyer?.email || '';
  const amount     = data.purchase?.payment?.value;
  const lang       = detectLangFromHotmart(data);

  const product = HOTMART_PRODUCTS[productId];

  if (product?.type === 'interpreter') {
    return handleInterpreterPurchase(product, buyerName, buyerEmail, lang, env, corsHeaders);
  }

  if (!product) {
    await sendTelegram(env,
      `⚠️ <b>Hotmart: неизвестный product_id</b>\n\n`
      + `ID: <code>${productId}</code>\n`
      + `Клиент: ${esc(buyerName)} · <code>${esc(buyerEmail)}</code>\n`
      + `Язык: ${lang}`
    );
    return jsonResponse({ ok: true, warning: 'unknown_product_id', productId }, corsHeaders);
  }

  const token = crypto.randomUUID();
  if (env.PROGRAM_INTAKES) {
    await env.PROGRAM_INTAKES.put('intake:' + token, JSON.stringify({
      token,
      email:      buyerEmail,
      name:       buyerName,
      program:    product.program,
      plan:       product.plan,
      price:      product.price,
      product_id: productId,
      lang,
      status:     'pending',
      ts:         new Date().toISOString(),
    }), { expirationTtl: 180 * 24 * 60 * 60 });
    // Метка «это программный клиент» по email → /cal-webhook не шлёт ему письмо VIA-L EXPERT
    // с анкетой (он уже получил большую анкету этим письмом об оплате).
    if (buyerEmail) {
      await env.PROGRAM_INTAKES.put('prog_email:' + buyerEmail.toLowerCase(), token, { expirationTtl: 180 * 24 * 60 * 60 });
    }
  }

  const programName = PROGRAM_NAMES[product.program] || product.program;
  const amountStr   = amount ? `€${amount}` : product.price;

  // Карточка в кабинете — сразу при оплате (ключ = token, тот же у анкеты программы).
  await cabinetUpsertFromPayment(env, {
    code: token, name: buyerName, email: buyerEmail, lang,
    product, program: programName, tier: product.plan, price: product.price, paidAmount: amountStr,
  });
  const langFlag    = { uk: '🇺🇦', ru: '🇷🇺', es: '🇪🇸', en: '🇬🇧', de: '🇩🇪', pt: '🇧🇷', fr: '🇫🇷', pl: '🇵🇱', it: '🇮🇹', he: '🇮🇱', ja: '🇯🇵', ko: '🇰🇷' }[lang] || '🌐';

  // Большая анкета здоровья (110 Q, book/anketa) с программным токеном — заполненная
  // вернётся в backstage с кнопкой «📅 Назначить сессию» (см. deliverAnketaProgram).
  // program-intake.html больше не используется.
  const intakeLink = `https://via-l.com/book/anketa/?lang=${lang}&intake=${token}`;

  await sendTelegram(env,
    `💳 <b>Новая оплата — ${programName}</b>\n`
    + `━━━━━━━━━━━━━━━━━━━━\n`
    + `👤 ${esc(buyerName)}\n`
    + `📧 <code>${esc(buyerEmail)}</code>\n`
    + `💰 ${amountStr} · ${product.plan}\n`
    + `${langFlag} Язык клиента: ${lang.toUpperCase()}\n`
    + `━━━━━━━━━━━━━━━━━━━━\n`
    + `📋 <b>Ссылка на анкету для клиента:</b>\n`
    + `<code>${intakeLink}</code>\n\n`
    + `Отправьте клиенту в Telegram или на email.`
  );

  // Email клієнту — посилання на анкету
  const et = EMAIL_T[lang] || EMAIL_T.en;
  await sendEmail(env, buyerEmail,
    et.payment_subj(programName),
    et.payment_body(buyerName, programName, intakeLink),
  );

  return jsonResponse({ ok: true, token, program: product.program, lang }, corsHeaders);
}

// ── Interpreter purchase: assign code + email buyer ───────────
async function handleInterpreterPurchase(product, buyerName, buyerEmail, lang, env, corsHeaders) {
  const TIER_NAMES = { 'VIAL-EXPERT-8W': 'VIA-L EXPERT · 8W', 'VIAL-EXPERT-12W': 'VIA-L EXPERT · 12W' };
  const tierName = TIER_NAMES[product.tier] || product.tier;
  const langFlag = { uk: '🇺🇦', ru: '🇷🇺', es: '🇪🇸', en: '🇬🇧', de: '🇩🇪', pt: '🇧🇷', fr: '🇫🇷', pl: '🇵🇱', it: '🇮🇹', he: '🇮🇱', ja: '🇯🇵', ko: '🇰🇷' }[lang] || '🌐';

  let code = null;
  let codeError = null;          // 'no_codes_available' | 'apps_script_unreachable' | 'apps_script_url_missing' | <other reason>
  if (env.APPS_SCRIPT_URL) {
    try {
      const r = await fetch(env.APPS_SCRIPT_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'assign_code', tier: product.tier }),
      });
      const j = await r.json();
      if (j.ok) code = j.code;
      else      codeError = j.reason || 'apps_script_error';
    } catch (e) {
      codeError = 'apps_script_unreachable';
    }
  } else {
    codeError = 'apps_script_url_missing';
  }

  await sendTelegram(env,
    `🧬 <b>Интерпретатор — ${tierName}</b>\n`
    + `━━━━━━━━━━━━━━━━━━━━\n`
    + `👤 ${esc(buyerName)}\n`
    + `📧 <code>${esc(buyerEmail)}</code>\n`
    + `💰 ${product.price}\n`
    + `${langFlag} ${lang.toUpperCase()}\n`
    + `━━━━━━━━━━━━━━━━━━━━\n`
    + (code ? `🔑 Код: <code>${code}</code>` : `⚠️ Код НЕ выдан (${esc(codeError || 'unknown')}) — см. алярм ниже`)
  );

  // Отдельный «жирный» алярм — только когда коды реально закончились в Sheets.
  // Не срабатывает при сетевых сбоях Apps Script: там TG-сообщение выше уже показало причину.
  if (codeError === 'no_codes_available') {
    await sendTelegram(env,
      `🚨 <b>КОДЫ ${esc(product.tier)} ЗАКОНЧИЛИСЬ</b>\n\n`
      + `В Google Sheets нет ни одного <code>FREE</code>-кода тарифа <code>${esc(product.tier)}</code>.\n`
      + `Покупатель ${esc(buyerName)} (<code>${esc(buyerEmail)}</code>) только что оплатил ${esc(product.price)} и <b>код не получил</b>.\n\n`
      + `Что делать:\n`
      + `1) Открыть <code>interpreter/code-generator.html</code>\n`
      + `2) Сгенерировать новую партию кодов <code>${esc(product.tier)}</code>\n`
      + `3) Загрузить CSV в Google Sheets (статус FREE)\n`
      + `4) Выдать код покупателю вручную (письмом или в TG)`
    );
  }

  // Связка «код → клиент» для «одного топика»: и сабмит анкеты, и /start care-бота находят
  // топик клиента по коду (code_topic). Здесь сохраняем язык/имя/email под кодом.
  if (code && env.EXPERT_DRAFTS) {
    await env.EXPERT_DRAFTS.put('code_owner:' + String(code).toUpperCase(),
      JSON.stringify({ email: buyerEmail || '', name: buyerName || '', lang }),
      { expirationTtl: 200 * 24 * 60 * 60 });
    // метка «клиент интерпретатора» — чтобы Cal-письмо НЕ дублировало анкету (он уже
    // получил её в подтверждении Expert-заявки, со ссылкой по коду).
    if (buyerEmail) await env.EXPERT_DRAFTS.put('interp_email:' + buyerEmail.toLowerCase(), '1',
      { expirationTtl: 200 * 24 * 60 * 60 });

    // Карточка в кабинете — при оплате (ключ = код доступа, тот же у care-анкеты).
    // Все ИП-продукты Hotmart теперь VIA-L EXPERT (гейт по PRO снят вместе с продуктом 7838739).
    await cabinetUpsertFromPayment(env, {
      code: String(code).toUpperCase(), name: buyerName, email: buyerEmail, lang,
      product, program: 'Интерпретатор (ИП)', tier: tierName, price: product.price, paidAmount: product.price,
    });
  }

  // Ссылку на анкету в письме НЕ дублируем: её даёт локализованное письмо-подтверждение
  // Expert-заявки (apps-script CLIENT_CONFIRM, 12 яз) — каждый VIA-L EXPERT получает её там.
  if (code && buyerEmail) {
    const mail = buildInterpreterEmailBody(buyerName, tierName, code, lang);
    await sendEmail(env, buyerEmail, mail.subject, mail.html);
  }

  return jsonResponse({ ok: true, tier: product.tier, code: code || null, code_error: codeError }, corsHeaders);
}

