function anketaVal(v){
  if(Array.isArray(v)) return v.join(', ');
  if(v && typeof v==='object') return Object.entries(v).map(([k,x])=>`    – ${k}: ${x}`).join('\n');
  return String(v);
}

// Разбивка строк карточки на куски ≤ limit (лимит Telegram 4096; держим запас под
// перевод, т.к. кириллица токеноёмкая и careTranslate ограничен 2000 токенов).
function anketaChunks(lines, limit=2500){
  const out=[]; let buf='';
  for(const ln of lines){
    if(buf && (buf+'\n'+ln).length>limit){ out.push(buf); buf=''; }
    buf = buf ? buf+'\n'+ln : ln;
  }
  if(buf) out.push(buf);
  return out;
}

// ИИ-структурирование: сырые ответы (язык клиента) → клиническая сводка на RU.
// Один вызов Sonnet 4.6 (анкета — разовое событие; качество важнее цены). Перевод
// встроен (вход на любом языке → выход RU). Возвращает '' при ошибке/без ключа.
async function anketaSummary(env, answers, lang){
  if(!env.CLAUDE_API_KEY) return '';
  const NAMES = {uk:'Ukrainian',ru:'Russian',en:'English',es:'Spanish',de:'German',pt:'Portuguese',fr:'French',pl:'Polish',it:'Italian',he:'Hebrew',ja:'Japanese',ko:'Korean'};
  const src = Object.values(answers).filter(it=>it && it.v!=null && it.v!=='')
    .map(it=>`${it.q||''}: ${anketaVal(it.v).replace(/\n\s*/g,'; ').trim()}`).join('\n');
  if(!src) return '';
  const system =
    'Ты — клинический ассистент нутрициолога VIA-L. На входе — ответы клиента из анкеты '+
    'здоровья (до 110 вопросов; язык клиента: '+(NAMES[lang]||lang)+'). Сделай СЖАТУЮ '+
    'структурированную сводку ДЛЯ НУТРИЦИОЛОГА на РУССКОМ языке строго по шаблону:\n'+
    '🎯 Цель клиента\n'+
    '🚩 Красные флаги (что требует внимания / направления к врачу; нет — пиши «нет явных»)\n'+
    '🔑 Ключевые жалобы по системам (энергия·сон / ЖКТ / гормоны / кожа·волосы / др.)\n'+
    '🧪 Анализы (что есть, что вне нормы, чего не хватает — доспросить)\n'+
    '💊 Лекарства и добавки (текущее + возможные дубли/взаимодействия)\n'+
    '🍽 Образ жизни (питание·сон·стресс·активность — точки коррекции)\n'+
    '📌 Фокус ведения (3–5 пунктов: с чего начать + что уточнить)\n\n'+
    'ПРАВИЛА: только систематизируй ответы клиента, ничего не выдумывай; нет данных — '+
    '«не указано». НЕ ставь диагнозы — медицинские находки помечай «рекомендовать '+
    'консультацию врача». Не выходи за рамки нутрициологии. Тон — забота, не приговор. '+
    'Без вступлений и заключений — только сводка по шаблону.\n'+
    'ФОРМАТ ВЫВОДА — ПРОСТОЙ ТЕКСТ для Telegram (parse_mode НЕ используется): '+
    'НЕ используй markdown-таблицы, символы | и решётки #/##/###, жирный **…**. '+
    'Только эмодзи-подзаголовки из шаблона, пункты через «•» или «–», и переносы строк. '+
    'Анализы давай списком «• Показатель: значение — статус», а не таблицей.';
  try{
    const res = await fetch('https://api.anthropic.com/v1/messages', {
      method:'POST',
      headers:{'Content-Type':'application/json','x-api-key':env.CLAUDE_API_KEY,'anthropic-version':'2023-06-01'},
      body: JSON.stringify({ model:'claude-sonnet-4-6', max_tokens:3000, system, messages:[{role:'user',content:src}] }),
    });
    if(!res.ok) return '';
    const j = await res.json();
    return (j.content?.[0]?.text||'').trim();
  }catch(_){ return ''; }
}

async function handleAnketaSubmit(request, env, corsHeaders, ctx){
  if(!env.CLIENT_BOT_TOKEN || !env.NUTRITIONIST_GROUP_ID || !env.EXPERT_DRAFTS){
    return jsonResponse({ok:false, error:'care bot not configured'}, corsHeaders, 503);
  }
  let body;
  try{ body = await request.json(); }catch(_){ return jsonResponse({ok:false, error:'bad json'}, corsHeaders, 400); }
  const answers = body.answers;
  if(!answers || typeof answers!=='object' || !Object.keys(answers).length){
    return jsonResponse({ok:false, error:'answers required'}, corsHeaders, 400);
  }
  // Тяжёлая часть (ИИ-сводка ~15–20с + доставка + email) уходит в ФОН: клиент не ждёт
  // ответ Sonnet, форма получает «✓ отправлено» мгновенно; ctx.waitUntil держит воркер
  // живым, карточка прилетает нутрициологу через несколько секунд. Без ctx (локально) —
  // выполняем синхронно.
  const job = deliverAnketa(env, body, answers, careLang(body.lang));
  if(ctx && ctx.waitUntil) ctx.waitUntil(job); else await job;
  return jsonResponse({ok:true}, corsHeaders);
}

// Фоновая доставка анкеты: топик → ИИ-сводка → полные ответы → email клиенту.
async function deliverAnketa(env, body, answers, lang){
  const get = id => answers[id]?.v;
  const name    = (typeof get('name')==='string' && get('name').trim()) ? get('name').trim() : '';
  const contact = (typeof get('contact')==='string') ? get('contact').trim() : '';
  const emailM  = contact.match(/[^\s@,;]+@[^\s@,;]+\.[^\s@,;]+/);
  const email   = emailM ? emailM[0] : '';

  // ── Анкета по реф-ссылке специалиста (?ref=<код>, канал 1, спека §10) ──
  // Привязываем пациента к специалисту (specialist_id), пишем анкету + согласие в его
  // карточку кабинета. Care-путь основателя (его TG-группа) для таких НЕ выполняется.
  const refCode = (typeof body.ref==='string' && body.ref.trim()) ? body.ref.trim().toUpperCase() : '';
  if(refCode && env.DB){
    let sp=null;
    try{ sp = await env.DB.prepare("SELECT id,name,lang FROM specialists WHERE upper(ref_code)=? AND status='active'").bind(refCode).first(); }catch(_){}
    if(sp){ await deliverAnketaRef(env, sp, refCode, answers, lang, name, email); return; }
  }

  // ── Программная анкета (ссылка из письма об оплате, ?intake=<token>) ──
  // Полная сводка → BACKSTAGE-бот (NUTRITIONIST_CHAT_ID) с кнопкой «📅 Назначить сессию»
  // (callback sched: обрабатывает /tg-webhook) → планирование Cal сохраняется. Care-путь
  // (care-группа) для таких НЕ выполняется. Невалидный токен → падаем в обычный care-путь.
  const intakeToken = (typeof body.intake==='string' && body.intake.trim()) ? body.intake.trim() : '';
  if(intakeToken && env.PROGRAM_INTAKES){
    const rawI = await env.PROGRAM_INTAKES.get('intake:'+intakeToken);
    if(rawI){
      let intake=null; try{ intake = JSON.parse(rawI); }catch(_){ intake=null; }
      if(intake){ await deliverAnketaProgram(env, intake, intakeToken, answers, lang, name, email); return; }
    }
  }

  // ── Куда нутрициологу: топик из /anketa, либо по КОДУ (связка с перепиской), либо новый ──
  // code_topic:<код> — единый «адрес» топика клиента: его пишет и сабмит анкеты, и /start
  // care-бота. Кто первый — создаёт, второй переиспользует → анкета и чат в ОДНОМ топике.
  const code = (typeof body.code==='string' && body.code.trim()) ? body.code.trim().toUpperCase() : '';
  let topicId = body.topic ? String(body.topic).replace(/\D/g,'') : '';
  if(topicId && !(await env.EXPERT_DRAFTS.get('care_client:'+topicId))) topicId = ''; // чужой/несуществующий
  if(!topicId && code) topicId = (await env.EXPERT_DRAFTS.get('code_topic:'+code)) || '';
  if(!topicId){
    topicId = await careCreateTopic(env, ((name||'Клиент')+' · анкета · '+lang.toUpperCase()).slice(0,128));
    if(topicId && code) await env.EXPERT_DRAFTS.put('code_topic:'+code, String(topicId));
  }
  const extra = topicId ? { message_thread_id: Number(topicId) } : {};
  const idline = `${name||'Клиент'}${email?' · '+email:''} · ${lang.toUpperCase()}`;

  // ── Сообщение 1: ИИ-сводка для нутрициолога (RU, перевод встроен) ──
  // Падение ИИ (нет ключа / ошибка) не блокирует доставку — полные ответы уйдут всё равно.
  const summary = await anketaSummary(env, answers, lang);

  // Этап 2: D1 — уписываем клиента + анкету (care path = VIA-L EXPERT по коду доступа)
  if(env.DB && code){
    const now = Date.now();
    let existing = null;
    try{ existing = await env.DB.prepare('SELECT data FROM clients WHERE code=?').bind(code).first(); }catch(_){}
    let dData = {};
    try{ dData = JSON.parse(existing?.data||'{}'); }catch(_){}
    dData.anketa = { answers, submitted_at: new Date().toISOString(), lang, summary: summary||'' };
    try{
      await env.DB.prepare(
        'INSERT INTO clients (code,name,email,lang,product,status,data,created_at,updated_at) VALUES (?,?,?,?,\'interpreter\',\'active\',?,?,?) ON CONFLICT(code) DO UPDATE SET name=CASE WHEN excluded.name!=\'\' THEN excluded.name ELSE name END, email=CASE WHEN excluded.email!=\'\' THEN excluded.email ELSE email END, lang=excluded.lang, data=excluded.data, updated_at=excluded.updated_at'
      ).bind(code, name||'', email||'', lang, JSON.stringify(dData), now, now).run();
    }catch(_){}
  }

  if(summary){
    for(const chunk of anketaChunks([`🧬 СВОДКА ДЛЯ НУТРИЦИОЛОГА · ${idline}`, '', ...summary.split('\n')])){
      await careSend(env, env.NUTRITIONIST_GROUP_ID, chunk, extra);
    }
  }

  // ── Сообщение 2: полные ответы как есть (язык клиента) — первоисточник ──
  const lines = [`📋 ПОЛНЫЕ ОТВЕТЫ · ${idline}`, ''];
  for(const item of Object.values(answers)){
    if(!item || item.v==null || item.v==='') continue;
    const val = anketaVal(item.v), q = item.q || '';
    lines.push(val.includes('\n') ? `• ${q}:\n${val}` : `• ${q}: ${val}`);
  }
  for(const chunk of anketaChunks(lines)){
    await careSend(env, env.NUTRITIONIST_GROUP_ID, chunk, extra);
  }

  // ── Подтверждение клиенту на email (гарантированный канал) ──
  if(email){
    const t = ANKETA_MAIL[lang] || ANKETA_MAIL.en;
    await sendEmail(env, email, t.subj, t.body(name));
  }
}

// Программная анкета: полная сводка + ответы + кнопка «📅 Назначить сессию» в BACKSTAGE-бота
// (NUTRITIONIST_CHAT_ID). HTML parse_mode → текст экранируем esc(). Обновляем запись интейка
// (status=submitted, answers) — её читает колбэк sched: при назначении сессии.
async function deliverAnketaProgram(env, intake, token, answers, lang, name, email){
  const progName = PROGRAM_NAMES[intake.program] || intake.program;
  const flag = {uk:'🇺🇦',ru:'🇷🇺',es:'🇪🇸',en:'🇬🇧',de:'🇩🇪',pt:'🇧🇷',fr:'🇫🇷',pl:'🇵🇱',it:'🇮🇹',he:'🇮🇱',ja:'🇯🇵',ko:'🇰🇷'}[lang]||'🌐';
  const cName  = name  || intake.name  || 'Клиент';
  const cEmail = email || intake.email || '';

  await env.PROGRAM_INTAKES.put('intake:'+token, JSON.stringify({
    ...intake, status:'submitted', answers, submitted_lang:lang, submitted_at:new Date().toISOString(),
  }), { expirationTtl: 180*24*60*60 });

  const head = `🧬 <b>Анкета здоровья · ${esc(progName)}</b>\n`
    + `━━━━━━━━━━━━━━━━━━━━\n`
    + `👤 <b>${esc(cName)}</b>\n`
    + (cEmail ? `📧 <code>${esc(cEmail)}</code>\n` : '')
    + `💰 ${esc(intake.price)} · ${esc(intake.plan)}\n`
    + `${flag} Заполнена на ${lang.toUpperCase()}\n`
    + `━━━━━━━━━━━━━━━━━━━━`;

  // ИИ-сводка (RU); падение ИИ не блокирует — ниже идут полные ответы и кнопка.
  const summary = await anketaSummary(env, answers, lang);

  // Этап 2: D1 — уписываем клиента + анкету (program path = site program)
  if(env.DB){
    const now = Date.now();
    let existing = null;
    try{ existing = await env.DB.prepare('SELECT data FROM clients WHERE code=?').bind(token).first(); }catch(_){}
    let dData = {};
    try{ dData = JSON.parse(existing?.data||'{}'); }catch(_){}
    dData.anketa = { answers, submitted_at: new Date().toISOString(), lang, summary: summary||'' };
    try{
      await env.DB.prepare(
        'INSERT INTO clients (code,name,email,lang,product,program,tier,price,status,data,created_at,updated_at) VALUES (?,?,?,?,\'site\',?,?,?,\'active\',?,?,?) ON CONFLICT(code) DO UPDATE SET name=CASE WHEN excluded.name!=\'\' THEN excluded.name ELSE name END, email=CASE WHEN excluded.email!=\'\' THEN excluded.email ELSE email END, lang=excluded.lang, data=excluded.data, updated_at=excluded.updated_at'
      ).bind(token, cName, cEmail, lang, intake.program||'', intake.plan||'', intake.price||'', JSON.stringify(dData), now, now).run();
    }catch(_){}
  }

  const sumLines = summary ? [head, '', ...summary.split('\n').map(esc)] : [head];
  for(const chunk of anketaChunks(sumLines, 3500)) await sendTelegram(env, chunk);

  // Полные ответы (первоисточник, язык клиента).
  const ansLines = ['📋 <b>ПОЛНЫЕ ОТВЕТЫ</b>', ''];
  for(const item of Object.values(answers)){
    if(!item || item.v==null || item.v==='') continue;
    const val = anketaVal(item.v), q = item.q || '';
    ansLines.push(val.includes('\n') ? `• <b>${esc(q)}:</b>\n${esc(val)}` : `• <b>${esc(q)}:</b> ${esc(val)}`);
  }
  for(const chunk of anketaChunks(ansLines, 3500)) await sendTelegram(env, chunk);

  // Кнопка планирования (тот же механизм, что был у program-intake).
  await sendTelegram(env, '✅ Анкета здоровья получена. Когда будете готовы — назначьте первую 60-мин сессию:',
    { reply_markup: buildIntakeKeyboard(token) });

  // Подтверждение клиенту на email.
  if(cEmail){
    const t = ANKETA_MAIL[lang] || ANKETA_MAIL.en;
    await sendEmail(env, cEmail, t.subj, t.body(cName));
  }
}

// ─────────────────────────────────────────────────────────────
// КАБИНЕТ: карточка рождается при ОПЛАТЕ (спека §2). Hotmart-вебхук уже знает
// имя/email/программу/тариф/язык — пишем карточку в D1 сразу, статус «new».
// Ключ = тот же код, по которому позже придёт анкета (token у программ сайта,
// код доступа у ИП) → анкета до-обогащает ТУ ЖЕ карточку, не создавая дубль.
// Формат сопровождения (Zoom/PDF/Разовая) и длительность — по тарифу+языку.
// ─────────────────────────────────────────────────────────────
function cabinetTariffMeta(product, lang){
  const ukRu = (lang === 'uk' || lang === 'ru');
  if (product.type === 'interpreter') {
    if (product.tier === 'VIAL-EXPERT-8W')  return { duration: 8,  format: ukRu ? 'zoom' : 'pdf' };
    if (product.tier === 'VIAL-EXPERT-12W') return { duration: 12, format: ukRu ? 'zoom' : 'pdf' };
    return { duration: null, format: 'pdf' };                                            // PRO в кабинет не пишем
  }
  const plan = product.plan || '';
  if (plan.includes('Разов')) return { duration: 1,  format: 'once' };                   // разовая (только uk/ru)
  if (plan.includes('8'))     return { duration: 8,  format: ukRu ? 'zoom' : 'pdf' };
  if (plan.includes('12'))    return { duration: 12, format: ukRu ? 'zoom' : 'pdf' };
  return { duration: null, format: ukRu ? 'zoom' : 'pdf' };
}

// Создаёт/обновляет карточку в D1 в момент оплаты. status='new' ставится только при
// INSERT (на конфликте не трогаем статус — у уже ведомого клиента он не сбросится).
// start_date НЕ задаём — старт ведения проставляет специалист в кабинете.
async function cabinetUpsertFromPayment(env, { code, name, email, lang, product, program, tier, price, paidAmount }){
  if (!env.DB || !code) return;
  const meta = cabinetTariffMeta(product, lang);
  const now  = Date.now();
  let existing = null;
  try { existing = await env.DB.prepare('SELECT data FROM clients WHERE code=?').bind(code).first(); } catch(_){}
  let data = {};
  try { data = JSON.parse(existing?.data || '{}'); } catch(_){}
  data.payment = { tier: tier||'', price: price||'', paid_amount: paidAmount||'', paid_at: new Date().toISOString() };
  const productKind = product.type === 'interpreter' ? 'interpreter' : 'site';
  try {
    await env.DB.prepare(
      `INSERT INTO clients (code,name,email,lang,product,program,tier,price,format,duration_weeks,status,data,created_at,updated_at)
       VALUES (?,?,?,?,?,?,?,?,?,?,'new',?,?,?)
       ON CONFLICT(code) DO UPDATE SET
         name=CASE WHEN excluded.name!='' THEN excluded.name ELSE name END,
         email=CASE WHEN excluded.email!='' THEN excluded.email ELSE email END,
         lang=excluded.lang, product=excluded.product, program=excluded.program,
         tier=excluded.tier, price=excluded.price, format=excluded.format,
         duration_weeks=excluded.duration_weeks, data=excluded.data, updated_at=excluded.updated_at`
    ).bind(
      code, name||'', email||'', lang||'', productKind, program||'', tier||'',
      price||'', meta.format, meta.duration, JSON.stringify(data), now, now
    ).run();
  } catch(_){}
}

// Ингест данных ИП-интерпретатора в карточку кабинета (вызывается из handleAnalyze).
// Привязка по коду доступа VIA-L EXPERT. UPDATE-only: если карточки нет — выходим
// (VIA-L/анонимные прогоны карточку не создают). Кладём: (1) недельный срез
// биометрики чистым маппингом ИП→кабинет (дедуп — один срез в день); (2) лог
// ИИ-разбора с полным текстом + ИП-метрики для контекста нутрициолога.
async function cabinetIngestIpAnalysis(env, code, data, analysisText, lang){
  if(!env.DB || !code) return;
  data = data || {};
  code = String(code).toUpperCase();
  const row = await env.DB.prepare('SELECT data FROM clients WHERE code=?').bind(code).first();
  if(!row) return;
  let d = {};
  try{ d = JSON.parse(row.data || '{}'); }catch(_){}
  // Пациент отозвал согласие (Шаг 2, /specialist/unlink) → новые разборы не пишем.
  // У платных VIA-L EXPERT поля sharing нет (undefined) → ингест работает как прежде.
  if(d.sharing === false) return;
  const today = new Date().toISOString().slice(0,10);

  // (1) Недельный срез биометрики — только чистый маппинг (hrv/rhr/weight). Один срез в день.
  if(!Array.isArray(d.biometrics)) d.biometrics = [];
  if(!d.biometrics.some(b => b.date === today)){
    const prevWeek = d.biometrics.length ? (parseInt(d.biometrics[d.biometrics.length-1].week) || d.biometrics.length) : 0;
    d.biometrics.push({
      week: prevWeek + 1, date: today,
      sleep:'', rhr: data.rhr || '', hrv: data.hrv || '', steps:'', weight: data.weight || '',
    });
  }

  // (2) Лог ИИ-разбора. Полный срез ИП — в metrics (контекст для нутрициолога).
  if(!Array.isArray(d.breakdowns)) d.breakdowns = [];
  d.breakdowns.push({
    date: today, type:'ai', status:'received', source:'ip', lang: lang || '',
    text: String(analysisText).slice(0, 6000),
    metrics: {
      hrv:data.hrv||'', rhr:data.rhr||'', sleep_qual:data.sleep_qual||'', energy:data.energy||'',
      anxiety:data.anxiety||'', temp:data.temp||'', weight:data.weight||'', device:data.device||'',
    },
  });
  if(d.breakdowns.length > 50) d.breakdowns = d.breakdowns.slice(-50);

  // (3) Дневной срез для «Динамики недели» в кабинете — полный набор метрик,
  // один на день (свежий перезаписывает), кап 30 дней. Источник для weeklyTrend.
  if(!Array.isArray(d.dyn)) d.dyn = [];
  const _num = x => { const v = parseFloat(x); return isNaN(v) ? null : v; };
  const dynEntry = {
    date: today, ts: Date.now(),
    hrv:_num(data.hrv), sleep:_num(data.sleep_qual), rhr:_num(data.rhr),
    energy:_num(data.energy), qol:_num(data._qol), anxiety:_num(data.anxiety), score:_num(data._score),
  };
  const _di = d.dyn.findIndex(x => x.date === today);
  if(_di >= 0) d.dyn[_di] = dynEntry; else d.dyn.push(dynEntry);
  if(d.dyn.length > 30) d.dyn = d.dyn.slice(-30);

  await env.DB.prepare('UPDATE clients SET data=?, updated_at=? WHERE code=?')
    .bind(JSON.stringify(d), Date.now(), code).run();
}

// Ингест реальной Cal.com-брони в карточку (вызов из handleCalWebhook). Привязка
// по email. Пишем в c.schedule с source='cal' + cal_uid (для апдейта при переносе/
// отмене). Так календарь кабинета показывает ФАКТИЧЕСКИЕ Zoom, а не только план.
// Нет карточки с таким email → выходим (знакомство до оплаты / внешний бронирующий).
async function cabinetIngestCalBooking(env, b){
  if(!env.DB || !b.email) return false;
  let row = null;
  try{ row = await env.DB.prepare('SELECT code,data FROM clients WHERE lower(email)=lower(?) LIMIT 1').bind(b.email).first(); }catch(_){}
  if(!row) return false;                              // нет карточки → вызывающий сохранит как лид
  let d = {}; try{ d = JSON.parse(row.data || '{}'); }catch(_){ return; }
  if(!Array.isArray(d.schedule)) d.schedule = [];
  const uid     = b.uid || (b.startTime + '|' + b.email);
  const date    = (b.startTime || '').slice(0,10);
  const timeStr = b.startTime ? (new Date(b.startTime).toISOString().slice(11,16) + ' UTC') : '';
  const idx = d.schedule.findIndex(s => s.cal_uid && s.cal_uid === uid);

  if(b.ev === 'BOOKING_CANCELLED'){
    if(idx < 0) return;
    d.schedule[idx].cancelled = true;
    d.schedule[idx].notes = 'Отменена (Cal.com)';
  } else {
    const entry = {
      date, type:'zoom', done:false, link: b.url || '', source:'cal', cal_uid: uid,
      cancelled:false, notes: ['Cal.com', timeStr, b.title].filter(Boolean).join(' · '),
    };
    if(idx >= 0) d.schedule[idx] = { ...d.schedule[idx], ...entry };
    else d.schedule.push(entry);
  }
  // упорядочим по дате — календарь и вкладка «Сессии» читают как есть
  d.schedule.sort((a,c) => String(a.date||'').localeCompare(String(c.date||'')));
  try{ await env.DB.prepare('UPDATE clients SET data=?, updated_at=? WHERE code=?')
    .bind(JSON.stringify(d), Date.now(), row.code).run(); }catch(_){}
  return true;
}

// Лид (15-мин знакомство до оплаты — карточки ещё нет). Храним в KV, чтобы бронь
// была видна в календаре кабинета (секция «Знакомства»). TTL 90 дн; ключ по uid.
async function cabinetSaveCalLead(env, b){
  if(!env.EXPERT_DRAFTS || !b.email) return;
  const uid = b.uid || (b.startTime + '|' + b.email);
  await env.EXPERT_DRAFTS.put('cal_lead:' + uid, JSON.stringify({
    name: b.name || '', email: b.email, date: (b.startTime || '').slice(0,10),
    time: b.startTime ? (new Date(b.startTime).toISOString().slice(11,16) + ' UTC') : '',
    url: b.url || '', title: b.title || '',
  }), { expirationTtl: 90 * 24 * 60 * 60 });
}
async function cabinetDeleteCalLead(env, uid){
  if(!env.EXPERT_DRAFTS || !uid) return;
  await env.EXPERT_DRAFTS.delete('cal_lead:' + uid);
}

// ─────────────────────────────────────────────────────────────
// БОТ-НАПОМИНАЛКА (Cron Trigger) — раз в день обходит активные карточки и шлёт
// клиентам напоминания в их ТГ-личку через care-бота. Триггеры:
//  • Zoom за 24 ч / в день встречи; • запрос данных за 24 ч / в день (PDF-формат);
//  • «нет данных N дней» — мягкий пинг. Дедуп: пометки в самой карточке (reminded_*,
//  last_data_nudge). Отправить можно только тем, у кого есть care-чат (нажал /start
//  у бота) — остальные пропускаются (Telegram не даёт писать первым).
// ─────────────────────────────────────────────────────────────
const REMIND_NO_DATA_DAYS = 5;

// Ссылка на интерпретатор клиента по тарифу (куда «пройти шаги ИП»). Только для
// ИП-клиентов (product='interpreter'); site-программы ИП не проходят.
function ipLinkFor(product, tier){
  if(product !== 'interpreter') return '';
  const t = String(tier || '').toUpperCase();
  if(t.includes('EXPERT')) return 'https://via-l.com/interpreter/interpreter-via-l-expert.html';   // VIA-L EXPERT (клон via-l-прохода)
  return 'https://via-l.com/interpreter';
}

function daysBetweenISO(a, b){
  const da = new Date(a + 'T00:00:00Z'), db = new Date(b + 'T00:00:00Z');
  return Math.round((db - da) / 86400000);
}

// code → topicId (code_topic) → clientId+lang (care_client / care_lang). null если чата нет.
async function resolveClientChat(env, code){
  if(!env.EXPERT_DRAFTS || !code) return null;
  const topicId = await env.EXPERT_DRAFTS.get('code_topic:' + String(code).toUpperCase());
  if(!topicId) return null;
  const raw = await env.EXPERT_DRAFTS.get('care_client:' + topicId);
  if(!raw) return null;
  let r = null; try{ r = JSON.parse(raw); }catch(_){ return null; }
  if(!r.clientId) return null;
  const lang = (await env.EXPERT_DRAFTS.get('care_lang:' + r.clientId)) || r.lang || 'en';
  return { clientId: r.clientId, lang, topicId };
}

// Шлёт клиенту (с переводом на его язык) + кладёт копию в топик нутрициолога для прозрачности.
async function sendClientReminder(env, ctx, ruText){
  let out = ruText;
  if(ctx.lang !== 'ru' && ctx.lang !== 'uk'){
    try{ out = await careTranslate(env, ruText, 'ru', ctx.lang); }catch(_){}
  }
  await careSend(env, ctx.clientId, out);
  if(ctx.topicId){
    await careSend(env, env.NUTRITIONIST_GROUP_ID, '🔔 Бот напомнил клиенту: ' + ruText, { message_thread_id: Number(ctx.topicId) });
  }
}

async function runDailyReminders(env){
  if(!env.DB) return;
  const todayStr    = new Date().toISOString().slice(0,10);
  const tomorrow    = new Date(); tomorrow.setUTCDate(tomorrow.getUTCDate()+1);
  const tomorrowStr = tomorrow.toISOString().slice(0,10);

  let results = [];
  try{
    const q = await env.DB.prepare("SELECT code,data,product,tier FROM clients WHERE status IN ('active','new')").all();
    results = q.results || [];
  }catch(_){ return; }

  for(const row of results){
    let d = {}; try{ d = JSON.parse(row.data || '{}'); }catch(_){ continue; }
    const cc = await resolveClientChat(env, row.code);
    if(!cc) continue;                                   // нет care-чата — написать нельзя
    let changed = false;

    // ИП-клиент проходит шаги в интерпретаторе (импорт с устройства + анализ) —
    // данные сами улетают в кабинет. Он НИЧЕГО не присылает и не знает про PDF
    // (PDF готовит нутрициолог). Поэтому для ИП зовём пройти ИП со ссылкой;
    // site-программы интерпретатор не проходят → нейтрально про самочувствие.
    const isIp   = row.product === 'interpreter';
    const ipLink = ipLinkFor(row.product, row.tier);
    const ipCall = ipLink ? ` Пройдите, пожалуйста, шаги в интерпретаторе (импорт данных с устройства + анализ) — это пара минут, а данные сами придут ко мне: ${ipLink}` : '';

    // 1+2+4 — точки расписания (Zoom/PDF) за 24 ч и в день встречи.
    // Тон — ЗАБОТА (ключевая ценность VIA-L): тепло, поддержка, без давления.
    for(const s of (d.schedule || [])){
      if(!s.date || s.done) continue;
      const isZoom = s.type === 'zoom' || s.type === 'once';
      if(s.date === tomorrowStr && !s.reminded_24h){
        await sendClientReminder(env, cc, isZoom
          ? `Здравствуйте! 🌿 С заботой напоминаю: завтра у нас с вами онлайн-встреча, я очень жду нашего разговора.${s.link ? ' Ссылка для подключения: ' + s.link : ''} Берегите себя.`
          : (isIp
              ? `Здравствуйте! 🌿 Завтра я подготовлю для вас персональный разбор.${ipCall} Спасибо вам, берегите себя!`
              : `Здравствуйте! 🌿 Завтра я подготовлю для вас персональный разбор. Поделитесь, пожалуйста, парой слов о самочувствии — так я смогу позаботиться о вас точнее. Спасибо вам.`));
        s.reminded_24h = true; changed = true;
      }
      if(s.date === todayStr && !s.reminded_day){
        await sendClientReminder(env, cc, isZoom
          ? `Доброе утро! 🌿 Сегодня у нас онлайн-встреча — я уже готовлюсь к нашему разговору.${s.link ? ' Ссылка: ' + s.link : ''} До скорой встречи, берегите себя!`
          : (isIp
              ? `Доброе утро! 🌿 Сегодня готовлю ваш разбор. Если ещё не успели — пройдите шаги в интерпретаторе, чтобы я учёл свежие данные:${ipLink ? ' ' + ipLink : ''} Спасибо, что заботитесь о себе!`
              : `Доброе утро! 🌿 Сегодня готовлю ваш разбор. Спасибо, что вы со мной — поделитесь, как ваше самочувствие.`));
        s.reminded_day = true; changed = true;
      }
    }

    // 3 — «нет данных N дней»: мягкая забота, без упрёка. Для ИП — зовём пройти ИП.
    const lastBio = (d.biometrics || []).slice(-1)[0];
    const sinceData  = lastBio?.date ? daysBetweenISO(lastBio.date, todayStr) : 999;
    const sinceNudge = d.last_data_nudge ? daysBetweenISO(d.last_data_nudge, todayStr) : 999;
    if(sinceData >= REMIND_NO_DATA_DAYS && sinceNudge >= REMIND_NO_DATA_DAYS){
      await sendClientReminder(env, cc, isIp
        ? `Здравствуйте! 🌿 Давно не было ваших данных — как самочувствие? Когда будет удобно, пройдите шаги в интерпретаторе, чтобы я продолжил вести вас точно:${ipLink ? ' ' + ipLink : ''} Я рядом и забочусь о вашем результате.`
        : `Здравствуйте! 🌿 Давно не было от вас вестей — как ваше самочувствие? Поделитесь, пожалуйста, когда будет удобно. Я рядом и забочусь о вашем результате.`);
      d.last_data_nudge = todayStr; changed = true;
    }

    if(changed){
      try{ await env.DB.prepare('UPDATE clients SET data=?, updated_at=? WHERE code=?')
        .bind(JSON.stringify(d), Date.now(), row.code).run(); }catch(_){}
    }
  }
}

// ─────────────────────────────────────────────────────────────
// КАБИНЕТ НУТРИЦИОЛОГА — лёгкий CRM на D1. См. docs/CABINET-MODEL.md.
// Этап 1: закрывает обе дыры прототипа — пароль уезжает из HTML в секрет
// CABINET_PASS (проверка в воркере + сессия-токен в KV + rate-limit), а данные
// клиентов переезжают из localStorage в D1 (env.DB). Источник правды = кабинет.
// Защищённые маршруты /cabinet/* требуют заголовок `Authorization: Bearer <token>`.
// ─────────────────────────────────────────────────────────────
// Сессия кабинета → { id, role } вошедшего специалиста, или null. Платформа, Шаг 3:
// токен теперь хранит, КТО вошёл (specialist_id + role), а не просто '1'.
// Старый формат значения '1' трактуем как владельца №1 (обратная совместимость токенов).
async function cabinetSession(request, env){
  if(!env.EXPERT_DRAFTS) return null;
  const h = request.headers.get('Authorization') || '';
  const token = h.startsWith('Bearer ') ? h.slice(7) : '';
  if(!token) return null;
  const raw = await env.EXPERT_DRAFTS.get('cabinet_sess:' + token);
  if(!raw) return null;
  if(raw === '1') return { id:1, role:'owner' };          // легаси-токен '1' = владелец
  try { const s = JSON.parse(raw); if(s && s.id) return { id:s.id, role:s.role || 'specialist' }; } catch(_){}
  return null;                                            // битое/непонятное значение → не пускаем (раньше ошибочно пускали владельцем)
}

// PBKDF2 (есть в Workers) — пароль специалиста хранится как "saltHex:hashHex".
function _cabHex(buf){ return [...new Uint8Array(buf)].map(b=>b.toString(16).padStart(2,'0')).join(''); }
function _cabUnhex(h){ const a=new Uint8Array(h.length/2); for(let i=0;i<a.length;i++) a[i]=parseInt(h.substr(i*2,2),16); return a; }
async function cabinetHashPassword(password, saltHex){
  const salt = saltHex ? _cabUnhex(saltHex) : crypto.getRandomValues(new Uint8Array(16));
  const key  = await crypto.subtle.importKey('raw', new TextEncoder().encode(password), { name:'PBKDF2' }, false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits({ name:'PBKDF2', salt, iterations:100000, hash:'SHA-256' }, key, 256);
  return _cabHex(salt) + ':' + _cabHex(bits);
}
async function cabinetVerifyPassword(password, stored){
  if(!stored || stored.indexOf(':') < 0) return false;
  const saltHex = stored.split(':')[0];
  const calc = await cabinetHashPassword(password, saltHex);
  return calc === stored;
}

// ── СТУПЕНИ ДОСТУПА ПРИ НЕОПЛАТЕ (C1, 2026-08-03) ───────────────────────────
// Было: cron ставил `lapsed` на следующий день после срока, и вход просто не работал —
// специалист получал «неверный пароль» и не понимал, что дело в деньгах. Хуже: он терял
// переписку с клиентами, которым обязан отвечать в 48 часов, — то есть били по клиенту,
// а не по должнику.
// Стало: сначала отключаем то, что ПОРОЖДАЕТ долг (выдачу новых доступов), и только потом
// ограничиваем работу. Оплаченные клиенты доигрывают всегда.
const GRACE_DAYS = 14;        // льготное окно после «оплачено до»
const RESTRICT_DAYS = 45;     // дальше — только чтение
function _accessStage(sp, today){
  if(!sp) return 'ok';
  if(String(sp.status||'') === 'disabled') return 'disabled';   // ручная блокировка владельцем
  if(sp.billing_exempt) return 'ok';                            // свой специалист — не облагаем
  if(!sp.platform_since) return 'ok';                           // абонплата не начисляется
  const paid = String(sp.access_paid_until||'').trim();
  if(!paid) return 'restricted';                                // ни разу не платил и уже подключён
  if(paid >= today) return 'ok';
  const d = (a,b) => Math.floor((new Date(b+'T00:00:00Z') - new Date(a+'T00:00:00Z')) / 86400000);
  const over = d(paid, today);
  if(over <= GRACE_DAYS) return 'grace';        // предупреждаем, ничего не отнимаем
  if(over <= RESTRICT_DAYS) return 'restricted';// нельзя выдавать НОВЫЕ доступы
  return 'readonly';                             // видит клиентов, не редактирует
}

async function handleCabinetAuth(request, env, corsHeaders){
  if(!env.EXPERT_DRAFTS){
    return jsonResponse({ ok:false, error:'cabinet_not_configured' }, corsHeaders, 500);
  }
  // rate-limit: 8 неудачных попыток за 10 мин на IP
  const ip      = request.headers.get('CF-Connecting-IP') || 'unknown';
  const failKey = 'cabinet_fail:' + ip;
  const fails   = parseInt(await env.EXPERT_DRAFTS.get(failKey) || '0', 10);
  if(fails >= 8) return jsonResponse({ ok:false, error:'rate_limited' }, corsHeaders, 429);

  let body = {};
  try { body = await request.json(); } catch(_){}
  const login = String(body.login || '').trim();
  const pass  = String(body.password || '');

  let session = null;
  if(login){
    // Вход специалиста по логину+паролю (только активный и с оплаченным доступом).
    if(env.DB){
      const sp = await env.DB.prepare(
        "SELECT id,role,pass_hash,status,access_status,access_paid_until,platform_since,billing_exempt FROM specialists WHERE lower(login)=lower(?)"
      ).bind(login).first();
      // Пароль проверяем ПЕРВЫМ: сообщать «просрочка» до проверки пароля значит подтверждать
      // чужому, что такой логин существует. Причина возвращается только своему.
      const passOk = sp && await cabinetVerifyPassword(pass, sp.pass_hash || '');
      if(passOk){
        const stage = _accessStage(sp, new Date().toISOString().slice(0,10));
        if(stage === 'disabled'){
          return jsonResponse({ ok:false, error:'disabled' }, corsHeaders, 403);
        }
        // На ступенях grace/restricted/readonly вход РАЗРЕШЁН: иначе страдают уже оплаченные
        // клиенты, которым специалист обязан отвечать. Ограничения — точечные, ниже по коду.
        session = { id: sp.id, role: sp.role || 'specialist', stage };
      }
    }
  } else if(env.CABINET_PASS && pass === env.CABINET_PASS){
    session = { id:1, role:'owner' };          // владелец через секрет CABINET_PASS
  }

  if(!session){
    await env.EXPERT_DRAFTS.put(failKey, String(fails + 1), { expirationTtl: 600 });
    return jsonResponse({ ok:false, error:'bad_password' }, corsHeaders, 401);
  }
  await env.EXPERT_DRAFTS.delete(failKey);
  const token = crypto.randomUUID().replace(/-/g,'') + crypto.randomUUID().replace(/-/g,'');
  await env.EXPERT_DRAFTS.put('cabinet_sess:' + token, JSON.stringify(session), { expirationTtl: 12 * 60 * 60 });
  // язык интерфейса + профиль вошедшего (локализация + вид под профиль) + реф-код/имя
  // (реф-код нужен фронту для блока «Моя ссылка для приглашения» — канал 1, спека §10).
  let lang = 'ru', specialty = 'nutritionist', refCode = '', name = '';
  let showcase = { public:0, photo:'', bio:'', cal_url:'', langs:'', category:'', pay_url:'' };   // профиль витрины «Мой наставник»
  if(env.DB){ try{ const r = await env.DB.prepare('SELECT lang,specialty,ref_code,name,public,photo,bio,cal_url,langs,category,pay_url FROM specialists WHERE id=?').bind(session.id).first(); if(r){ if(r.lang) lang = r.lang; if(r.specialty) specialty = r.specialty; if(r.ref_code) refCode = r.ref_code; if(r.name) name = r.name; showcase = { public: r.public?1:0, photo: r.photo||'', bio: r.bio||'', cal_url: r.cal_url||'', langs: r.langs||'', category: r.category||'', pay_url: r.pay_url||'' }; } }catch(_){} }
  return jsonResponse({ ok:true, token, role: session.role, lang, specialty, ref_code: refCode, name, showcase }, corsHeaders);
}

// POST /cabinet/showcase-save {public, photo, bio, cal_url, langs} — специалист правит СВОЙ профиль витрины.
async function handleCabinetShowcaseSave(request, env, corsHeaders){
  const sess = await cabinetSession(request, env);
  if(!sess) return jsonResponse({ ok:false, error:'unauthorized' }, corsHeaders, 401);
  if(!env.DB) return jsonResponse({ ok:false, error:'d1_missing' }, corsHeaders, 500);
  let b={}; try{ b = await request.json(); }catch(_){}
  const pub   = (b.public===true || b.public===1 || b.public==='1') ? 1 : 0;
  const photo = String(b.photo||'').trim().slice(0,2000);
  const bio   = String(b.bio||'').trim().slice(0,600);
  const cal   = String(b.cal_url||'').trim().slice(0,500);
  const langs = String(b.langs||'').trim().slice(0,120);
  // Ссылка на оплату ведения (Hotmart/Stripe/др. чекаут специалиста). Мы храним ТОЛЬКО URL:
  // никаких карт, счетов и реквизитов — деньги идут напрямую специалисту, платформа их не касается.
  // Пускаем лишь http(s), чтобы в кнопку витрины нельзя было подсунуть javascript:.
  let pay = String(b.pay_url||'').trim().slice(0,500);
  if(pay && !/^https?:\/\//i.test(pay)) pay = '';
  const CATS = ['nutrition','psychology','fitness','medical'];
  const category = CATS.includes(b.category) ? b.category : '';
  await env.DB.prepare('UPDATE specialists SET public=?, photo=?, bio=?, cal_url=?, langs=?, category=?, pay_url=? WHERE id=?')
    .bind(pub, photo, bio, cal, langs, category, pay, sess.id).run();
  return jsonResponse({ ok:true, showcase:{ public:pub, photo, bio, cal_url:cal, langs, category, pay_url:pay } }, corsHeaders);
}

// Лёгкий список: колонки-шапка + только нужные списку/календарю куски data через
// json_extract (НЕ тянем тяжёлые anketa/messages/protocol). Чинит лимит ответа D1.
const CABINET_LIST_COLS = `code,name,email,tg,phone,lang,product,program,tier,duration_weeks,price,format,
  start_date,end_date,status,gender,age,phase,specialist_id,created_at,updated_at,
  json_extract(data,'$.phase_label')         AS phase_label,
  json_extract(data,'$.schedule')            AS j_schedule,
  json_array_length(data,'$.biometrics')     AS bio_n,
  json_array_length(data,'$.breakdowns')     AS bd_n,
  json_extract(data,'$.biometrics[#-1].hrv') AS last_hrv,
  json_extract(data,'$.sharing')             AS sharing,
  json_extract(data,'$.consent.ref_code')    AS consent_ref`;

// D1-строка лёгкого запроса → объект для списка/календаря (без полного досье).
function cabinetRowToLight(r){
  let schedule = [];
  try { schedule = r.j_schedule ? JSON.parse(r.j_schedule) : []; } catch(_){}
  const bioN = r.bio_n || 0, bdN = r.bd_n || 0;
  return {
    id: r.code, code:r.code, name:r.name, email:r.email, tg:r.tg, phone:r.phone, lang:r.lang,
    product:r.product, program:r.program, tier:r.tier, duration_weeks:r.duration_weeks,
    price:r.price, format:r.format, start_date:r.start_date, end_date:r.end_date,
    status:r.status, gender:r.gender, age:r.age, phase:r.phase, phase_label:r.phase_label||'',
    specialist_id:r.specialist_id, created_at:r.created_at, updated_at:r.updated_at,
    schedule,                                              // календарю нужны все будущие точки
    biometrics: bioN > 0 ? [{ hrv: r.last_hrv }] : [],     // календарю нужен только последний hrv
    breakdowns: bdN > 0 ? new Array(bdN) : [],             // бейджу нужна только длина
    sharing: r.sharing === 1 || r.sharing === true,
    consent: r.consent_ref ? { ref_code: r.consent_ref } : undefined,
    _light: true,                                          // полное досье ещё не загружено
  };
}

// D1-строка → объект клиента (полное досье лежит в JSON-колонке data; колонки —
// зеркало для списка/поиска). Возвращаем плоский объект в форме, которую ждёт фронт.
function cabinetRowToClient(r){
  let data = {};
  try { data = JSON.parse(r.data || '{}'); } catch(_){}
  return {
    ...data,
    // code — сквозной первичный ключ (спека §2). Фронт идентифицирует карточку по id;
    // у клиентов из воронки (deliverAnketa*) id нет — подставляем code, иначе карточка не откроется.
    id: data.id || r.code,
    code:r.code, name:r.name, email:r.email, tg:r.tg, phone:r.phone, lang:r.lang,
    product:r.product, program:r.program, tier:r.tier, duration_weeks:r.duration_weeks,
    price:r.price, format:r.format, start_date:r.start_date, end_date:r.end_date,
    status:r.status, gender:r.gender, age:r.age, phase:r.phase,
    specialist_id:r.specialist_id,
    created_at:r.created_at, updated_at:r.updated_at,
  };
}

async function handleCabinetClients(request, env, corsHeaders){
  const sess = await cabinetSession(request, env);
  if(!sess) return jsonResponse({ ok:false, error:'unauthorized' }, corsHeaders, 401);
  if(!env.DB) return jsonResponse({ ok:false, error:'d1_missing' }, corsHeaders, 500);
  // Владелец видит всех; специалист — только своих (specialist_id = его id).
  // Лёгкий запрос: без тяжёлого data, только колонки-шапка + производные (CABINET_LIST_COLS).
  const { results } = sess.role === 'owner'
    ? await env.DB.prepare('SELECT ' + CABINET_LIST_COLS + ' FROM clients ORDER BY updated_at DESC').all()
    : await env.DB.prepare('SELECT ' + CABINET_LIST_COLS + ' FROM clients WHERE specialist_id=? ORDER BY updated_at DESC').bind(sess.id).all();
  // C2: кабинет должен показать баннер «просрочка, к оплате €N» — иначе специалист
  // упирается в ограничения и не понимает причину.
  let stage = 'ok', dueNow = 0;
  try{
    const me = await env.DB.prepare(
      'SELECT status,access_paid_until,platform_since,billing_exempt FROM specialists WHERE id=?'
    ).bind(sess.id).first();
    stage = _accessStage(me, new Date().toISOString().slice(0,10));
    if(stage !== 'ok' && me && me.platform_since && !me.billing_exempt){
      const g = await env.DB.prepare('SELECT COALESCE(SUM(owed_eur),0) o FROM grants WHERE specialist_id=?').bind(sess.id).first();
      const p = await env.DB.prepare("SELECT COALESCE(SUM(amount_eur),0) p FROM payments WHERE specialist_id=? AND kind='software'").bind(sess.id).first();
      const soft = Math.max(0, ((g&&g.o)||0) - ((p&&p.p)||0));
      const paid = String(me.access_paid_until||'').trim();
      const today = new Date().toISOString().slice(0,10);
      const months = paid ? Math.max(0, _monthsBetween(_addMonths(paid,1), today)) : _monthsBetween(me.platform_since, today);
      dueNow = Math.round((soft + months * PLATFORM_FEE_EUR) * 100) / 100;
    }
  }catch(_){}
  let specialty = 'nutritionist', refCode = '', name = '';
  let showcase = { public:0, photo:'', bio:'', cal_url:'', langs:'', category:'', pay_url:'' };
  try{ const sp = await env.DB.prepare('SELECT specialty,ref_code,name,public,photo,bio,cal_url,langs,category,pay_url FROM specialists WHERE id=?').bind(sess.id).first(); if(sp){ if(sp.specialty) specialty = sp.specialty; if(sp.ref_code) refCode = sp.ref_code; if(sp.name) name = sp.name; showcase = { public: sp.public?1:0, photo: sp.photo||'', bio: sp.bio||'', cal_url: sp.cal_url||'', langs: sp.langs||'', category: sp.category||'', pay_url: sp.pay_url||'' }; } }catch(_){}
  return jsonResponse({ ok:true, access_stage: stage, due_now: dueNow, clients:(results || []).map(cabinetRowToLight), role:sess.role, specialty, ref_code: refCode, name, showcase }, corsHeaders);
}

// Полное досье одного клиента (карточка по требованию) — изоляция через cabinetOwns.
async function handleCabinetClient(request, env, corsHeaders){
  const sess = await cabinetSession(request, env);
  if(!sess) return jsonResponse({ ok:false, error:'unauthorized' }, corsHeaders, 401);
  if(!env.DB) return jsonResponse({ ok:false, error:'d1_missing' }, corsHeaders, 500);
  let code = '';
  try { const b = await request.json(); code = String(b.code || b.id || ''); } catch(_){}
  if(!code) return jsonResponse({ ok:false, error:'no_code' }, corsHeaders, 400);
  if(!await cabinetOwns(env, sess, code)) return jsonResponse({ ok:false, error:'forbidden' }, corsHeaders, 403);
  const r = await env.DB.prepare('SELECT * FROM clients WHERE code=?').bind(code).first();
  if(!r) return jsonResponse({ ok:false, error:'not_found' }, corsHeaders, 404);
  return jsonResponse({ ok:true, client: cabinetRowToClient(r) }, corsHeaders);
}

async function handleCabinetSave(request, env, corsHeaders){
  const sess = await cabinetSession(request, env);
  if(!sess) return jsonResponse({ ok:false, error:'unauthorized' }, corsHeaders, 401);
  if(!env.DB) return jsonResponse({ ok:false, error:'d1_missing' }, corsHeaders, 500);

  let c = {};
  try { c = (await request.json()).client || {}; } catch(_){}
  const code = String(c.code || c.id || '');           // до Этапа 2 код = id прототипа
  if(!code) return jsonResponse({ ok:false, error:'no_code' }, corsHeaders, 400);

  // Анти-разбухание досье (CABINET-MODEL §8): режем неограниченно растущие массивы,
  // чтобы строка клиента не упёрлась в лимит ответа D1 раньше времени.
  if(Array.isArray(c.messages) && c.messages.length > 300) c.messages = c.messages.slice(-300);
  if(Array.isArray(c.notes)    && c.notes.length    > 300) c.notes    = c.notes.slice(-300);

  // Владелец правит любого; специалист — только своего. Решаем специалиста для записи.
  const existing = await env.DB.prepare('SELECT specialist_id FROM clients WHERE code=?').bind(code).first();
  if(sess.role !== 'owner' && existing && existing.specialist_id != null && existing.specialist_id !== sess.id){
    return jsonResponse({ ok:false, error:'forbidden' }, corsHeaders, 403);
  }
  const specId = sess.role === 'owner'
    ? (c.specialist_id != null ? c.specialist_id : (existing ? existing.specialist_id : 1))
    : sess.id;                                          // специалист всегда сохраняет на себя

  const now  = Date.now();
  const data = JSON.stringify(c);                       // полное досье целиком
  if(data.length > 262144) return jsonResponse({ ok:false, error:'client_too_large' }, corsHeaders, 413); // потолок ~256 КБ на карточку
  const age  = (c.age === '' || c.age == null) ? null : parseInt(c.age, 10);
  const dur  = (c.duration_weeks == null || c.duration_weeks === '') ? null : parseInt(c.duration_weeks, 10);

  await env.DB.prepare(`
    INSERT INTO clients
      (code,name,email,tg,phone,lang,product,program,tier,duration_weeks,price,format,
       start_date,end_date,status,gender,age,phase,specialist_id,data,created_at,updated_at)
    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
    ON CONFLICT(code) DO UPDATE SET
      name=excluded.name, email=excluded.email, tg=excluded.tg, phone=excluded.phone, lang=excluded.lang,
      product=excluded.product, program=excluded.program, tier=excluded.tier, duration_weeks=excluded.duration_weeks,
      price=excluded.price, format=excluded.format, start_date=excluded.start_date, end_date=excluded.end_date,
      status=excluded.status, gender=excluded.gender, age=excluded.age, phase=excluded.phase,
      specialist_id=excluded.specialist_id, data=excluded.data, updated_at=excluded.updated_at
  `).bind(
    code, c.name||'', c.email||'', c.tg||'', c.phone||'', c.lang||'',
    c.product||'', c.program||'', c.tier||'', dur, c.price||'', c.format||'',
    c.start_date||'', c.end_date||'', c.status||'active', c.gender||'', age, c.phase||'',
    specId, data, c.created_at || now, now
  ).run();

  return jsonResponse({ ok:true, code }, corsHeaders);
}

// Проверка «этот клиент принадлежит вошедшему» (владельцу — любой). true = можно.
async function cabinetOwns(env, sess, code){
  if(sess.role === 'owner') return true;
  if(!env.DB) return false;                              // нет БД — проверить владение нельзя → не пускаем
  const r = await env.DB.prepare('SELECT specialist_id FROM clients WHERE code=?').bind(code).first();
  return !!(r && r.specialist_id === sess.id);
}

async function handleCabinetDelete(request, env, corsHeaders){
  const sess = await cabinetSession(request, env);
  if(!sess) return jsonResponse({ ok:false, error:'unauthorized' }, corsHeaders, 401);
  if(!env.DB) return jsonResponse({ ok:false, error:'d1_missing' }, corsHeaders, 500);
  let code = '';
  try { const b = await request.json(); code = String(b.code || b.id || ''); } catch(_){}
  if(!code) return jsonResponse({ ok:false, error:'no_code' }, corsHeaders, 400);
  if(!await cabinetOwns(env, sess, code)) return jsonResponse({ ok:false, error:'forbidden' }, corsHeaders, 403);
  await env.DB.prepare('DELETE FROM clients WHERE code=?').bind(code).run();
  return jsonResponse({ ok:true }, corsHeaders);
}

// Платформа, Шаг 5 (мост перевода). Имена языков для промпта + выбор модели
// (he/ja/ko/ar → Sonnet, как в careTranslate и основном ИП — не откатывать, см. memory).
const CAB_LANG_NAMES = {uk:'украинском',ru:'русском',en:'английском',es:'испанском',de:'немецком',pt:'португальском',fr:'французском',pl:'польском',it:'итальянском',he:'иврите',ja:'японском',ko:'корейском'};
function cabModelForLang(l){ return ['he','ja','ko','ar'].includes(l) ? 'claude-sonnet-4-6' : 'claude-haiku-4-5-20251001'; }
async function cabSpecialistLang(env, sess){
  if(!env.DB || !sess) return 'ru';
  try{ const sp = await env.DB.prepare('SELECT lang FROM specialists WHERE id=?').bind(sess.id).first(); return (sp && sp.lang) || 'ru'; }catch(_){ return 'ru'; }
}

// Шаг 5: перевод произвольного текста на язык вошедшего специалиста (кнопки «Перевести»
// на анкете/переписке). Движок — careTranslate (тот же роутинг модели).
async function handleCabinetTranslate(request, env, corsHeaders){
  const sess = await cabinetSession(request, env);
  if(!sess) return jsonResponse({ok:false,error:'unauthorized'}, corsHeaders, 401);
  if(!env.CLAUDE_API_KEY) return jsonResponse({ok:false,error:'no_claude_key'}, corsHeaders, 500);
  let b={}; try{ b=await request.json(); }catch(_){}
  const text = String(b.text||'');
  if(!text) return jsonResponse({ok:false,error:'no_text'}, corsHeaders, 400);
  const to   = String(b.to||'').trim() || await cabSpecialistLang(env, sess);
  const from = String(b.from||'').trim();
  const translated = await careTranslate(env, text, from, to);
  return jsonResponse({ok:true, text:translated, to}, corsHeaders);
}

// Этап 4: ИИ-черновик ответа клиенту (для нутрициолога, в кабинете).
// Шаг 5: черновик генерируется на ЯЗЫКЕ ВОШЕДШЕГО специалиста (владелец ru → как раньше).
async function handleCabinetAiDraft(request, env, corsHeaders){
  const sess = await cabinetSession(request, env);
  if(!sess) return jsonResponse({ok:false,error:'unauthorized'}, corsHeaders, 401);
  if(!env.DB) return jsonResponse({ok:false,error:'d1_missing'}, corsHeaders, 500);
  if(!env.CLAUDE_API_KEY) return jsonResponse({ok:false,error:'no_claude_key'}, corsHeaders, 500);
  let body={};
  try{ body=await request.json(); }catch(_){}
  const code=String(body.code||'').trim();
  if(!code) return jsonResponse({ok:false,error:'no_code'}, corsHeaders, 400);
  if(!await cabinetOwns(env, sess, code)) return jsonResponse({ok:false,error:'forbidden'}, corsHeaders, 403);

  const spLang   = await cabSpecialistLang(env, sess);          // язык вошедшего специалиста
  const langName = CAB_LANG_NAMES[spLang] || 'русском';

  const row=await env.DB.prepare('SELECT name,lang,program,tier,data FROM clients WHERE code=?').bind(code).first();
  if(!row) return jsonResponse({ok:false,error:'not_found'}, corsHeaders, 404);

  let data={};
  try{ data=JSON.parse(row.data||'{}'); }catch(_){}

  const anketa   = data.anketa || {};
  const bio      = (data.biometrics||[]).slice(-4);
  const msgs     = (data.messages||[]).slice(-8);

  const ctxLines = [
    `Клиент: ${row.name||'Клиент'} · Программа: ${row.program||'—'} · Тариф: ${row.tier||'—'} · Язык: ${row.lang||'—'}`,
    anketa.summary ? `Анкета (ИИ-сводка): ${anketa.summary}` : null,
    bio.length ? 'Последние биометрики:\n' + bio.map(b=>`  Нед.${b.week||'?'}: Сон ${b.sleep||'?'}ч, ЧСС ${b.rhr||'?'}, HRV ${b.hrv||'?'}`).join('\n') : null,
    msgs.length ? 'Последние сообщения:\n' + msgs.map(m=>`  [${m.dir==='in'?'Клиент':'Нутрициолог'}] ${m.text||''}`).join('\n') : null,
  ].filter(Boolean).join('\n');

  const prompt =
    'Ты ассистент нутрициолога VIA-L. Составь черновик ответного сообщения клиенту на ' + langName + ' языке. ' +
    'ГЛАВНАЯ ЦЕННОСТЬ VIA-L — ЗАБОТА о клиенте: пиши тепло, по-человечески, с искренней поддержкой и вниманием к его состоянию, ' +
    'без давления и формализма; клиент должен чувствовать, что о нём заботятся, а не обрабатывают. ' +
    'При этом оставайся профессиональным и конкретным. Только нутрициологические рекомендации — не ставь диагнозы, не назначай лекарства. ' +
    'Объём: 3–5 предложений. БЕЗ Markdown-разметки (никаких ** __ —). ' +
    'БЕЗ вступления «Здравствуйте» и подписи — только суть ответа.\n\n' +
    'Данные клиента:\n' + ctxLines;

  try{
    const res = await fetch('https://api.anthropic.com/v1/messages', {
      method:'POST',
      headers:{'Content-Type':'application/json','x-api-key':env.CLAUDE_API_KEY,'anthropic-version':'2023-06-01'},
      body:JSON.stringify({model:cabModelForLang(spLang),max_tokens:500,messages:[{role:'user',content:prompt}]}),
    });
    const j = await res.json();
    const draft = j?.content?.[0]?.text || '';
    return jsonResponse({ok:true, draft}, corsHeaders);
  }catch(e){
    return jsonResponse({ok:false,error:e.message}, corsHeaders, 500);
  }
}

// Этап 4: отправка сообщения в ТГ-топик клиента (care-группа, через CLIENT_BOT_TOKEN).
// Ищет topicId по code_topic:<code> в EXPERT_DRAFTS.
// POST /cabinet/chat-send {code, text} — ответ специалиста ИЗ КАБИНЕТА прямо в чат клиента
// (VIA-L EXPERT app), а не только в Telegram. Пишет {dir:'out',source:'cabinet'} в data.messages
// (оригинал на языке спеца — /expert/thread переведёт клиенту на чтение). Опц. зеркало в TG-топик.
// См. tasks/TODO.md «Свой чат — ответ специалиста из кабинета», [[project_own_chat_reply_gap]].
async function handleCabinetChatSend(request, env, corsHeaders, ctx){
  const sess = await cabinetSession(request, env);
  if(!sess) return jsonResponse({ok:false,error:'unauthorized'}, corsHeaders, 401);
  if(!env.DB) return jsonResponse({ok:false,error:'d1_missing'}, corsHeaders, 500);
  let body={}; try{ body=await request.json(); }catch(_){}
  const code = String(body.code||'').trim();
  const text = String(body.text||'').trim().slice(0,4000);
  const mtype = (body.type==='image'||body.type==='audio') ? body.type : '';
  const murl  = String(body.url||'').slice(0,500);
  if(!code || (!text && !(mtype && murl))) return jsonResponse({ok:false,error:'missing_fields'}, corsHeaders, 400);
  if(!await cabinetOwns(env, sess, code)) return jsonResponse({ok:false,error:'forbidden'}, corsHeaders, 403);
  const row = await env.DB.prepare('SELECT data FROM clients WHERE code=?').bind(code).first();
  if(!row) return jsonResponse({ok:false,error:'not_found'}, corsHeaders, 404);
  let d={}; try{ d=JSON.parse(row.data||'{}'); }catch(_){}
  if(!Array.isArray(d.messages)) d.messages=[];
  const date = new Date().toISOString().slice(0,10);
  const outMsg = { dir:'out', date, text, source:'cabinet' };
  if(mtype && murl){ outMsg.type = mtype; outMsg.url = murl; }
  d.messages.push(outMsg);
  if(d.messages.length>300) d.messages=d.messages.slice(-300);
  await env.DB.prepare('UPDATE clients SET data=?, updated_at=? WHERE code=?').bind(JSON.stringify(d), Date.now(), code).run();
  // Опц. зеркало в Telegram-топик (специалист-оператор в TG видит continuity) — не блокируем ответ.
  if(ctx && env.CLIENT_BOT_TOKEN && env.NUTRITIONIST_GROUP_ID && env.EXPERT_DRAFTS){
    ctx.waitUntil((async()=>{
      try{ const topicId = await env.EXPERT_DRAFTS.get('code_topic:'+code); const tgText = text || (mtype==='image'?'📷 '+murl:mtype==='audio'?'🎤 '+murl:''); if(topicId && tgText) await careSend(env, env.NUTRITIONIST_GROUP_ID, tgText, {message_thread_id:Number(topicId)}); }catch(_){}
    })());
  }
  return jsonResponse({ ok:true, date }, corsHeaders);
}

async function handleCabinetTgSend(request, env, corsHeaders){
  const sess = await cabinetSession(request, env);
  if(!sess) return jsonResponse({ok:false,error:'unauthorized'}, corsHeaders, 401);
  if(!env.CLIENT_BOT_TOKEN || !env.NUTRITIONIST_GROUP_ID) return jsonResponse({ok:false,error:'tg_not_configured'}, corsHeaders, 500);
  let body={};
  try{ body=await request.json(); }catch(_){}
  const code = String(body.code||'').trim();
  const text = String(body.text||'').trim();
  if(!code || !text) return jsonResponse({ok:false,error:'missing_fields'}, corsHeaders, 400);
  if(!await cabinetOwns(env, sess, code)) return jsonResponse({ok:false,error:'forbidden'}, corsHeaders, 403);

  // Шаг 5: авто-перевод на язык пациента, если он отличается от языка специалиста.
  let outText = text, translated = false;
  if(env.DB){
    const spLang = await cabSpecialistLang(env, sess);
    let clientLang = '';
    try{ const cl = await env.DB.prepare('SELECT lang FROM clients WHERE code=?').bind(code).first(); clientLang = (cl && cl.lang) || ''; }catch(_){}
    if(clientLang && spLang && clientLang !== spLang){
      const t = await careTranslate(env, text, spLang, clientLang);
      if(t && t !== text){ outText = t; translated = true; }
    }
  }

  let topicId = '';
  if(env.EXPERT_DRAFTS) topicId = (await env.EXPERT_DRAFTS.get('code_topic:'+code)) || '';

  const extra = topicId ? {message_thread_id: Number(topicId)} : {};
  const res = await careSend(env, env.NUTRITIONIST_GROUP_ID, outText, extra);
  const ok = !!(res && (res.ok || res.result));
  return jsonResponse({ok, topicId: topicId||null, translated}, corsHeaders);
}

// Лиды-знакомства (Cal.com-брони без оплаченной карточки) для секции «Знакомства»
// в календаре кабинета. Возвращаем только будущие, отсортированные по дате.
async function handleCabinetLeads(request, env, corsHeaders){
  const sess = await cabinetSession(request, env);
  if(!sess) return jsonResponse({ok:false,error:'unauthorized'}, corsHeaders, 401);
  // Лиды-знакомства — воронка основателя; показываем только владельцу.
  if(sess.role !== 'owner') return jsonResponse({ok:true, leads:[]}, corsHeaders);
  if(!env.EXPERT_DRAFTS) return jsonResponse({ok:true, leads:[]}, corsHeaders);
  const today = new Date().toISOString().slice(0,10);
  // Email-ы уже оплативших клиентов — таких НЕ показываем в «знакомствах» (у них есть карточка).
  const paid = new Set();
  try{
    const rows = env.DB ? (await env.DB.prepare('SELECT email FROM clients').all()).results : [];
    for(const r of (rows||[])){ if(r.email) paid.add(String(r.email).toLowerCase()); }
  }catch(_){}
  const leads = [];
  try{
    const list = await env.EXPERT_DRAFTS.list({ prefix:'cal_lead:' });
    for(const k of (list.keys||[])){
      const raw = await env.EXPERT_DRAFTS.get(k.name);
      if(!raw) continue;
      let v=null; try{ v=JSON.parse(raw); }catch(_){ continue; }
      if(v && v.date && v.date >= today && !paid.has(String(v.email||'').toLowerCase())) leads.push(v);
    }
  }catch(_){}
  leads.sort((a,b)=>String(a.date).localeCompare(String(b.date)));
  return jsonResponse({ok:true, leads}, corsHeaders);
}

// ─────────────────────────────────────────────────────────────
// ПЛАТФОРМА, ШАГ 2 — пациент подключается к специалисту.
// Пациент уже пользуется ИП (подписка в App Store/Google Play). Он вводит КОД
// СПЕЦИАЛИСТА (specialists.ref_code) и даёт СОГЛАСИЕ → создаётся/привязывается
// карточка под этим специалистом, и его ИП-разборы текут в неё по уже работающему
// ингесту (cabinetIngestIpAnalysis по коду). См. docs/PLATFORM-MODEL.md §3.
// ─────────────────────────────────────────────────────────────

// Алфавит кодов доступа: без похожих на глаз 0/O и 1/I — коды диктуют голосом и
// переписывают из письма. Ровно 32 символа, а 256 кратно 32 → `byte % 32` даёт
// равномерное распределение без смещения, отбраковка байтов не нужна.
const CODE_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';

// Случайная часть кода — из crypto.getRandomValues, НЕ из Math.random: код доступа
// открывает личный дневник клиента и его карточку, а Math.random не криптостойкий
// (его поток в принципе предсказуем по нескольким выданным значениям).
function _randCode(len){
  const buf = new Uint8Array(len);
  crypto.getRandomValues(buf);
  let s = '';
  for(let i=0;i<len;i++) s += CODE_ALPHABET[buf[i] % 32];
  return s;
}

// Код пациента: P + 6 знаков. Под ним пациент проходит ИП,
// по нему же разборы попадают в его карточку.
function genPatientCode(){ return 'P' + _randCode(6); }

// Срочный код доступа к VIA-L EXPERT (префикс EX — визуально отличим от кода карточки P…).
function genExpertCode(){ return 'EX' + _randCode(7); }

// Persist статуса выданного доступа в карточку клиента (data.expert_grant) — чтобы Кабинет
// показывал активный доступ после релоада (KV сам по себе фронту не виден). Read-merge-write.
async function _setCardExpertGrant(env, cardCode, patch){
  if(!env.DB || !cardCode) return;
  try{
    const row = await env.DB.prepare('SELECT data FROM clients WHERE code=?').bind(cardCode).first();
    if(!row) return;
    let d={}; try{ d = JSON.parse(row.data || '{}'); }catch(_){}
    d.expert_grant = Object.assign({}, d.expert_grant || {}, patch);
    await env.DB.prepare('UPDATE clients SET data=?, updated_at=? WHERE code=?')
      .bind(JSON.stringify(d), Date.now(), cardCode).run();
  }catch(_){}
}

// ── ЖУРНАЛ ВЫДАЧ В D1 (бухгалтерская правда) ──────────────────
// KV-запись доступа живёт «срок + 60 дней» и потом исчезает вместе с суммой начисления,
// а перебрать KV по специалисту нельзя. Поэтому каждая выдача/продление/отзыв дублируется
// строкой в D1 `grants` (миграция cabinet-step9-billing.sql): по ней и считается, кто сколько
// должен за софт. Пишем НЕ в фоне: расхождение журнала с доступом дороже пары миллисекунд.
async function _grantLog(env, rec, grantCode){
  if(!env.DB || !grantCode) return;
  try{
    const now = Date.now();
    await env.DB.prepare(
      `INSERT INTO grants (code, card_code, specialist_id, plan, days, owed_eur, issued, expiry, revoked, revoked_at, created_at, updated_at)
       VALUES (?,?,?,?,?,?,?,?,?,?,?,?)
       ON CONFLICT(code) DO UPDATE SET
         days=excluded.days, owed_eur=excluded.owed_eur, expiry=excluded.expiry,
         revoked=excluded.revoked, revoked_at=excluded.revoked_at, updated_at=excluded.updated_at`
    ).bind(grantCode, rec.card_code || null, rec.specialist_id || null, rec.plan || null,
           rec.days || 0, rec.owed || 0, rec.issued || new Date().toISOString().slice(0,10),
           rec.expiry || null, rec.revoked ? 1 : 0, rec.revoked ? new Date().toISOString().slice(0,10) : null,
           now, now).run();
  }catch(e){ /* журнал не должен ломать выдачу доступа */ }
}

// ── Воронка витрина → EXPERT PWA: выдача/проверка/отзыв срочного кода доступа ──
// Хранилище — KV EXPERT_DRAFTS, ключ `expert_access:<GRANTCODE>`:
//   { card_code, plan, expiry(YYYY-MM-DD), quota, used, revoked, specialist_id, days, owed, issued }
// card_code = код карточки клиента (из /specialist/connect) → разборы текут по нему в кабинет.
// GRANTCODE отдельный: истёк/отозван → вход закрыт, но карточка и привязка живы.

// ══ АККАУНТ КЛИЕНТА ПО КОДУ: серверное состояние ИП (`/expert/state`) ══════════
// Задача: один код = один аккаунт. Раньше дневник/профиль/разборы жили только в
// localStorage устройства, а PWA на телефоне и браузер — это РАЗНЫЕ хранилища
// (у standalone-PWA свой контейнер), поэтому один клиент выглядел как несколько
// разных, и что именно доедет в кабинет было лотереей. Теперь состояние хранится
// в KV `ipstate:<КОД>` и подтягивается на любом устройстве после ввода кода.
//
// Сервер здесь — ТУПОЕ хранилище с CAS, вся логика слияния на клиенте:
//   { rev, updated, keys: { <ключ localStorage>: { t:<метка изменения>, v:<строка> } } }
// Запись принимается только если baseRev совпал с текущим rev; иначе 409 + актуальный
// снимок → клиент сливает у себя и повторяет. Так два устройства не затирают друг друга.
// Авторизация — код доступа (та же модель, что у /expert/message и /weekly-report).
const IPSTATE_MAX = 3 * 1024 * 1024;                    // потолок снимка (KV держит до 25МБ; 3МБ ≈ годы дневника)
const IPSTATE_TTL = 400 * 24 * 60 * 60;                 // самоочистка через ~13 мес после последней записи

// GET /expert/state?code= → {ok, rev, keys}. Нет записи → rev:0, keys:{} (новый аккаунт).
async function handleExpertStateGet(request, env, corsHeaders){
  const code = String(new URL(request.url).searchParams.get('code')||'').trim().toUpperCase();
  if(!code) return jsonResponse({ ok:false, error:'no_code' }, corsHeaders, 400);
  if(!env.EXPERT_DRAFTS) return jsonResponse({ ok:false, error:'backend_missing' }, corsHeaders, 500);
  let rec=null;
  try{ rec = JSON.parse(await env.EXPERT_DRAFTS.get('ipstate:'+code) || 'null'); }catch(_){}
  return jsonResponse({ ok:true, rev:(rec&&rec.rev)||0, updated:(rec&&rec.updated)||'', keys:(rec&&rec.keys)||{} }, corsHeaders);
}

// POST /expert/state {code, baseRev, keys} → {ok, rev} | 409 {ok:false, conflict:true, rev, keys}
async function handleExpertStatePut(request, env, corsHeaders){
  if(!env.EXPERT_DRAFTS) return jsonResponse({ ok:false, error:'backend_missing' }, corsHeaders, 500);
  let b={}; try{ b = await request.json(); }catch(_){}
  const code = String(b.code||'').trim().toUpperCase();
  const keys = (b.keys && typeof b.keys==='object') ? b.keys : null;
  if(!code || !keys) return jsonResponse({ ok:false, error:'bad_request' }, corsHeaders, 400);

  let rec=null;
  try{ rec = JSON.parse(await env.EXPERT_DRAFTS.get('ipstate:'+code) || 'null'); }catch(_){}
  const curRev = (rec && rec.rev) || 0;
  if(Number(b.baseRev||0) !== curRev)
    return jsonResponse({ ok:false, conflict:true, rev:curRev, keys:(rec&&rec.keys)||{} }, corsHeaders, 409);

  const next = { rev: curRev + 1, updated: new Date().toISOString(), keys };
  const body = JSON.stringify(next);
  if(body.length > IPSTATE_MAX) return jsonResponse({ ok:false, error:'too_large' }, corsHeaders, 413);
  await env.EXPERT_DRAFTS.put('ipstate:'+code, body, { expirationTtl: IPSTATE_TTL });
  return jsonResponse({ ok:true, rev: next.rev }, corsHeaders);
}

// GET /expert/verify?code= — гейт EXPERT дёргает первым. Отдаёт ту же форму, что Apps Script
// (ok, plan, expiry, expert_used, expert_max), + code=card_code (по нему гейт роутит разборы).
async function handleExpertVerify(request, env, corsHeaders){
  const code = String(new URL(request.url).searchParams.get('code')||'').trim().toUpperCase();
  if(!code) return jsonResponse({ ok:false, reason:'invalid' }, corsHeaders, 400);
  if(!env.EXPERT_DRAFTS) return jsonResponse({ ok:false, reason:'not_found' }, corsHeaders);
  let rec=null;
  try{ rec = JSON.parse(await env.EXPERT_DRAFTS.get('expert_access:'+code) || 'null'); }catch(_){}
  if(!rec) return jsonResponse({ ok:false, reason:'not_found' }, corsHeaders);   // не наш → гейт уйдёт в Apps Script
  if(rec.revoked) return jsonResponse({ ok:false, reason:'revoked' }, corsHeaders);
  const today = new Date().toISOString().slice(0,10);
  if(rec.expiry && today > rec.expiry) return jsonResponse({ ok:false, reason:'expired' }, corsHeaders);
  return jsonResponse({
    ok:true, code: rec.card_code || code, plan: rec.plan || 'VIAL-EXPERT-8W',
    expiry: rec.expiry || '', expert_used: rec.used || 0, expert_max: rec.quota || 0
  }, corsHeaders);
}

// POST /cabinet/expert-grant  {code, days, plan?} — специалист выдаёт клиенту доступ к EXPERT.
// code = код карточки клиента; days = срок ведения (1 разбор/день → quota=days); owed = days/30×€20.
async function handleCabinetExpertGrant(request, env, corsHeaders){
  const sess = await cabinetSession(request, env);
  if(!sess) return jsonResponse({ ok:false, error:'unauthorized' }, corsHeaders, 401);
  if(!env.DB || !env.EXPERT_DRAFTS) return jsonResponse({ ok:false, error:'backend_missing' }, corsHeaders, 500);
  let b={}; try{ b = await request.json(); }catch(_){}
  const cardCode = String(b.code||'').trim().toUpperCase();
  const days = Math.max(1, Math.min(400, parseInt(b.days,10)||0));
  if(!cardCode) return jsonResponse({ ok:false, error:'no_code' }, corsHeaders, 400);
  if(!days)     return jsonResponse({ ok:false, error:'no_days' }, corsHeaders, 400);

  // карточка должна существовать и (для не-владельца) принадлежать вошедшему специалисту
  // A3: непроверенный специалист не может выдавать доступы — это отсекает случайных людей
  // на входе, а не после жалоб. Владелец не гейтится (он и проверяет).
  if(sess.role !== 'owner'){
    const me = await env.DB.prepare(
      'SELECT verified,status,access_paid_until,platform_since,billing_exempt,credit_limit FROM specialists WHERE id=?'
    ).bind(sess.id).first();
    if(!me || !me.verified) return jsonResponse({ ok:false, error:'not_verified' }, corsHeaders, 403);
    // C1: просрочка бьёт по тому, что порождает долг, — по выдаче НОВЫХ доступов.
    // Текущие ведения и переписка продолжают работать: клиент уже заплатил.
    const stage = _accessStage(me, new Date().toISOString().slice(0,10));
    if(stage === 'restricted' || stage === 'readonly' || stage === 'disabled')
      return jsonResponse({ ok:false, error:'payment_required', stage }, corsHeaders, 402);

    // C3: КВОТА-ПРЕДОХРАНИТЕЛЬ. Модель «доверие + счёт» — это постоплата: специалист выдаёт
    // доступы, долг растёт, платит потом. Если он исчезнет, неоплаченный софт остаётся на нас.
    // Лимит ограничивает максимальный убыток заранее и известной величиной. Владелец может
    // поднять его тому, кто себя показал, — это и есть «доверие», только измеримое.
    if(!me.billing_exempt){
      const limit = (me.credit_limit == null) ? 100 : +me.credit_limit;
      if(limit > 0){
        const g = await env.DB.prepare('SELECT COALESCE(SUM(owed_eur),0) o FROM grants WHERE specialist_id=?').bind(sess.id).first();
        const p = await env.DB.prepare("SELECT COALESCE(SUM(amount_eur),0) p FROM payments WHERE specialist_id=? AND kind='software'").bind(sess.id).first();
        const outstanding = Math.max(0, ((g&&g.o)||0) - ((p&&p.p)||0));
        const willAdd = Math.round(days / 30 * 20);
        if(outstanding + willAdd > limit)
          return jsonResponse({ ok:false, error:'credit_limit', limit, outstanding,
                                need: Math.round((outstanding + willAdd - limit) * 100) / 100 }, corsHeaders, 402);
      }
    }
  }
  const row = await env.DB.prepare('SELECT specialist_id FROM clients WHERE code=?').bind(cardCode).first();
  if(!row) return jsonResponse({ ok:false, error:'client_not_found' }, corsHeaders, 404);
  if(sess.role !== 'owner' && String(row.specialist_id) !== String(sess.id))
    return jsonResponse({ ok:false, error:'forbidden' }, corsHeaders, 403);

  const today = new Date();
  const exp = new Date(today.getTime()); exp.setUTCDate(exp.getUTCDate() + days);
  const expiry = exp.toISOString().slice(0,10);
  const owed = Math.round(days / 30 * 20);   // €20/мес софт (закладка в цену специалиста)

  // уникальный код (пара попыток на случай коллизии)
  let grantCode = genExpertCode();
  for(let i=0;i<3;i++){ if(!(await env.EXPERT_DRAFTS.get('expert_access:'+grantCode))) break; grantCode = genExpertCode(); }

  const rec = {
    card_code: cardCode, plan: String(b.plan||('CUSTOM-'+days+'D')).toUpperCase(),
    expiry, quota: days, used: 0, revoked: false,
    specialist_id: sess.id, days, owed, issued: today.toISOString().slice(0,10)
  };
  await env.EXPERT_DRAFTS.put('expert_access:'+grantCode, JSON.stringify(rec),
    { expirationTtl: (days + 60) * 24 * 60 * 60 });   // авто-очистка через срок + 60 дней
  await _setCardExpertGrant(env, cardCode, { code:grantCode, expiry, days, owed, revoked:false, issued:rec.issued });
  await _grantLog(env, rec, grantCode);   // начисление за софт → в журнал бухгалтерии

  const link = 'https://via-l.com/interpreter/interpreter-via-l-expert.html';
  return jsonResponse({ ok:true, code: grantCode, expiry, days, owed, link }, corsHeaders);
}

// POST /cabinet/expert-extend {code} (code = GRANTCODE) {days} — продлить срок доступа.
async function handleCabinetExpertExtend(request, env, corsHeaders){
  const sess = await cabinetSession(request, env);
  if(!sess) return jsonResponse({ ok:false, error:'unauthorized' }, corsHeaders, 401);
  if(!env.EXPERT_DRAFTS) return jsonResponse({ ok:false, error:'backend_missing' }, corsHeaders, 500);
  let b={}; try{ b = await request.json(); }catch(_){}
  const grantCode = String(b.code||'').trim().toUpperCase();
  const add = Math.max(1, Math.min(400, parseInt(b.days,10)||0));
  if(!grantCode || !add) return jsonResponse({ ok:false, error:'bad_input' }, corsHeaders, 400);
  let rec=null; try{ rec = JSON.parse(await env.EXPERT_DRAFTS.get('expert_access:'+grantCode) || 'null'); }catch(_){}
  if(!rec) return jsonResponse({ ok:false, error:'not_found' }, corsHeaders, 404);
  if(sess.role !== 'owner' && String(rec.specialist_id) !== String(sess.id))
    return jsonResponse({ ok:false, error:'forbidden' }, corsHeaders, 403);
  // продлеваем от max(сегодня, текущий expiry)
  const today = new Date().toISOString().slice(0,10);
  const base = (rec.expiry && rec.expiry > today) ? new Date(rec.expiry+'T00:00:00Z') : new Date();
  base.setUTCDate(base.getUTCDate() + add);
  rec.expiry = base.toISOString().slice(0,10);
  rec.quota = (rec.quota||0) + add;
  rec.days  = (rec.days||0) + add;
  rec.owed  = Math.round(rec.days / 30 * 20);
  rec.revoked = false;
  await env.EXPERT_DRAFTS.put('expert_access:'+grantCode, JSON.stringify(rec), { expirationTtl: (rec.days + 60) * 24 * 60 * 60 });
  await _setCardExpertGrant(env, rec.card_code, { code:grantCode, expiry:rec.expiry, days:rec.days, owed:rec.owed, revoked:false });
  await _grantLog(env, rec, grantCode);   // пересчитанное начисление → в журнал
  return jsonResponse({ ok:true, code:grantCode, expiry:rec.expiry, days:rec.days, owed:rec.owed }, corsHeaders);
}

// POST /cabinet/expert-revoke  {code} — специалист закрывает выданный доступ (code = GRANTCODE).
async function handleCabinetExpertRevoke(request, env, corsHeaders){
  const sess = await cabinetSession(request, env);
  if(!sess) return jsonResponse({ ok:false, error:'unauthorized' }, corsHeaders, 401);
  if(!env.EXPERT_DRAFTS) return jsonResponse({ ok:false, error:'backend_missing' }, corsHeaders, 500);
  let b={}; try{ b = await request.json(); }catch(_){}
  const grantCode = String(b.code||'').trim().toUpperCase();
  if(!grantCode) return jsonResponse({ ok:false, error:'no_code' }, corsHeaders, 400);
  let rec=null; try{ rec = JSON.parse(await env.EXPERT_DRAFTS.get('expert_access:'+grantCode) || 'null'); }catch(_){}
  if(!rec) return jsonResponse({ ok:false, error:'not_found' }, corsHeaders, 404);
  if(sess.role !== 'owner' && String(rec.specialist_id) !== String(sess.id))
    return jsonResponse({ ok:false, error:'forbidden' }, corsHeaders, 403);
  rec.revoked = true;
  await env.EXPERT_DRAFTS.put('expert_access:'+grantCode, JSON.stringify(rec), { expirationTtl: 60*24*60*60 });
  await _setCardExpertGrant(env, rec.card_code, { revoked:true });
  await _grantLog(env, rec, grantCode);   // строка остаётся: за отработанное начислено
  return jsonResponse({ ok:true, code:grantCode, revoked:true }, corsHeaders);
}

// Анкета по реф-ссылке (канал 1): привязать пациента к специалисту + записать анкету/согласие
// в его карточку. Реюз карточки по email, иначе новый код пациента. ИП-разборы потекут по коду.
async function deliverAnketaRef(env, sp, refCode, answers, lang, name, email){
  if(!env.DB) return;
  const now = Date.now();
  let existing = null;
  if(email){ try{ existing = await env.DB.prepare('SELECT code,data FROM clients WHERE lower(email)=lower(?) LIMIT 1').bind(email).first(); }catch(_){} }
  const code = existing ? existing.code : genPatientCode();
  let dData = {};
  try{ dData = JSON.parse(existing?.data||'{}'); }catch(_){}
  const summary = await anketaSummary(env, answers, lang);
  dData.anketa  = { answers, submitted_at: new Date().toISOString(), lang, summary: summary||'' };
  dData.consent = { at: new Date().toISOString(), ref_code: refCode, specialist_id: sp.id };
  dData.sharing = true;
  await env.DB.prepare(`
    INSERT INTO clients (code,name,email,lang,product,status,specialist_id,data,created_at,updated_at)
    VALUES (?,?,?,?,'interpreter','active',?,?,?,?)
    ON CONFLICT(code) DO UPDATE SET
      name=CASE WHEN excluded.name!='' THEN excluded.name ELSE name END,
      email=CASE WHEN excluded.email!='' THEN excluded.email ELSE email END,
      lang=excluded.lang, specialist_id=excluded.specialist_id,
      data=excluded.data, updated_at=excluded.updated_at
  `).bind(code, name||'', email||'', sp.lang||lang||'', sp.id, JSON.stringify(dData), now, now).run();
  if(env.EXPERT_DRAFTS){
    await env.EXPERT_DRAFTS.put('code_owner:'+code,
      JSON.stringify({ email, name, lang: sp.lang||lang||'' }),
      { expirationTtl: 200*24*60*60 });
  }
}

// Публичный GET: имя/профиль активного специалиста по его реф-коду (для де-брендинга анкеты).
// GET /specialists/public — витрина: активные наставники с флагом public=1.
// НЕ отдаёт ref_code (код специалист даёт клиенту после зума → сохраняем воронку витрина→знакомство).
async function handleSpecialistsPublic(request, env, corsHeaders){
  if(!env.DB) return jsonResponse({ok:false,error:'d1_missing'}, corsHeaders, 500);
  let rows=[];
  try{
    const r = await env.DB.prepare(
      "SELECT id,name,specialty,category,photo,bio,cal_url,langs,pay_url,education,reg_number,website,city,country,legal_form,insurance,verified_at FROM specialists WHERE public=1 AND COALESCE(verified,0)=1 AND status='active' ORDER BY name"
    ).all();
    rows = r.results || [];
  }catch(_){}
  // pay_url отдаём как ссылку для кнопки «Начать ведение» — текстом её витрина не показывает.
  return jsonResponse({ ok:true, specialists: rows.map(s=>({
    id:s.id, name:s.name||'', specialty:s.specialty||'', category:s.category||'', photo:s.photo||'',
    bio:s.bio||'', cal_url:s.cal_url||'', langs:s.langs||'', pay_url:s.pay_url||'',
    // A3: то, ради чего клиент открывает карточку — чем человек подтверждает, что он специалист.
    // Служебное (юр. имя, налоговый номер, адрес, телефон, договор) сюда НЕ попадает никогда.
    education:s.education||'', reg_number:s.reg_number||'', website:s.website||'',
    city:s.city||'', verified_at:s.verified_at||'',
    // Страна и юр. статус публичны намеренно: от страны специалиста зависит применимое право
    // в договоре с клиентом, и клиент обязан видеть это ДО оплаты, а не в споре.
    country:s.country||'', legal_form:s.legal_form||'',
    insurance: s.insurance?1:0
  })) }, corsHeaders);
}

